INSERT INTO `adik_adik` (`id`, `title`, `slug`, `content`, `photo`, `time_create`, `time_update`, `is_published`, `cat_id`) VALUES
(1, 'Введение', 'Vvedenie', 'Учимся делать сайты на радость себе и людям!\r\n\r\nВсе очень просто!\r\nДля  начала научимся создавать простые интернет-страницы.\r\nЧто для этого нужно? Любой текстовый редактор, например Блокнот или WordPad.\r\nЗапустите эту программу через Пуск - Все программы - Стандартные - Блокнот (WordPad).\r\nТеперь скопируйте вот этот код (или наберите )\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Моя первая страничка </title>\r\n</head>\r\n<body>\r\nПривет мир!!!\r\n<br>\r\nМеня зовут (здесь впишите Ваше имя), это моя первая страничка!\r\n</body>\r\n</html> \r\n\r\nи вставьте его в Блокнот или WordPad.\r\nТеперь выберите команду в меню  Файл-Сохранить как\r\nУкажите заранее созданную папку для сохранения файла. (Рекомендую сделать отдельную папку для работы, например папку sites на любом диске (например C или любой другой )\r\nВ поле тип файла выберите \"текстовый документ\" с расширением *.txt\r\nВ поле имя файла введите index.html (имя -index можно другое, а расширение обязательно укажите .html так как по умолчанию блокнот\r\nпредлагает сохранить файл с расширением *.txt). Проверьте в нужную ли папку сохраняется файл.\r\nНажмите кнопку \"Сохранить\". Если выскочит окошко, предупреждающее о потери форматирования - нажмите Ок.\r\nТеперь зайдите в папку где вы сохранили файл. Если вы все сделали правильно - то он должен иметь значек(логотип браузера) интернет-страницы (если вдруг не так – значит, вы забыли указать .html когда сохраняли файл). Запустите этот файл. Вы увидите вашу первую интернет-страничку!\r\nКак видите - ничего сложного.', 'bg-showcase-3.jpg', '2025-07-03 16:09:04.000000', '2025-07-03 16:09:04.000000', 1, 1),
(2, 'Основные теги', 'osnovnie-tegi', '\r\nТеперь давайте разберемся и усвоим то, что мы писали. Интернет-глобальная сеть. Для получения информации пользователи Тиспользуют разные браузеры.\r\nДля создания страниц используется HTML (Hyper Text Marker Language) - универсальный язык гипертекстовой разметки страниц,который понимают все пользователи(браузеры)\r\nРазметка страницы происходит с помощью так называемых тегов.\r\nВсе команды которые вы видите в скобках <..> - это все теги.\r\nТеги бывают парные и не парные. Большинство тегов парные и состоят из открывающего и закрывающего тега.\r\nТак например тег <head> открывающий, а тег </head> закрывающий. Как видите, открывающий тег от закрывающего отличается лишь наклонной чертой / Открывающий и закрывающий тег по типу <…> </…> представляет собой своего рода\r\nѐмкость, ящик в который могут складываться другие теги - ящички поменьше.. следовательно, выглядеть так:<Тег \"большой ящик\">\r\n<Тег \"ящик средний\">\r\n<Тег \"ящик маленький\">\r\nсодержание\r\n</Тег \"ящик маленький\" >\r\n</Тег \"ящик средний\" >\r\n</Тег \"большой ящик\">\r\nТеперь о минимальном наборе тегов для создания html страницы.\r\nДля того чтобы компьютер и наш браузер знал что имеет дело с html-страницей - надо написать вот эту парочку\r\n<!DOCTYPE html>\r\n........\r\n</html>\r\n\r\n( !DOCTYPE — обязательная вставка принятая согласно действующего соглашения (подробнее об этом в другой раз)\r\nДалее, подобно человеку, html-страница имеет голову (head) и тело (body). По такой ассоциации легко запомнить структуру создания html-страницы. Поэтому добавляются парные теги \"головы\" и \"тела\"\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n \r\n<head>\r\n</head>\r\n \r\n<body>\r\n</body>\r\n \r\n</html>\r\n\r\nКаждая страница должна иметь название. Это название отражается в названии окна вашего браузера. Название страницы пишется между тегами <title> и </title> , которые должны располагаться в \"голове\".\r\n\r\n<!DOCTYPE html> \r\n<html lang=\"ru\">\r\n<head>\r\n<title>Здесь пишется название страницы</ </title>\r\n</head>\r\n \r\n<body>Здесь пишем содержание нашей страницы\r\n</body>\r\n \r\n</html>\r\n\r\nНу а сам собственно текст страницы (а также рисунки, таблицы и прочие объекты) пишется в \"теле\":\r\n<body>\r\nЗдесь пишем содержание нашей страницы\r\n</body>\r\nТеги внутри себя могут иметь различные атрибуты в нашем примете использован атрибут атрибут lang тега <html> для указания языка на котором написан документ и может быть задан в любом месте и для любого тега', 'photos/2025/$m/14/testimonials-3.jpg', '2025-07-14 10:17:48.958570', '2025-07-14 10:17:48.958630', 1, 1),
(3, 'Применение тегов', 'primenenie', '\r\nВы знаете, что такое параграф.. это такой кусочек текста, одно или несколько\r\nпредложений, который в книгах обычно печатается с новой строки. Для того чтобы на странице сайта разбить текст на параграфы, необходимо\r\nвоспользоваться тегом <p> - собственно параграф. Параграф имеет атрибут align \"выравнивание\" который в свою очередь может быть равен\r\nтому ли иному значению. Например с помощью параграфа можно расположить текст по центру:\r\n<p align=\"center\">Привет мир!!!</p>\r\nПо левому краю:\r\n<p align=\"left\">Привет мир!!!</p>\r\nПо правому краю:\r\n<p align=\"right\">Привет мир!!!</p>\r\nИли же обоим краям документа:\r\n<p align=\"justify\">Привет мир!!! - здесь нужен текст по длиней чтобы эффект был\r\nхорошо виден при открытии документа</p>\r\nПо умолчанию Ваш текст выравнивается браузером по левому краю, так что если Вам так\r\nи надо атрибут align=\"left\" для параграфа можно не указывать. Тег <p> подразумевает в себе перенос строки, если это Вам не нужно, используйте вместо\r\nтега <p> тег <div> данный тег является альтернативой тегу <p> пишится так:\r\n<div align=\"center\">Привет мир!!!</div>\r\n<div align=\"left\">Привет мир!!!</div>\r\n<div align=\"right\">Привет мир!!!</div>\r\n<div align=\"justify\">Привет мир!!!</div>\r\nДавайте слегка изменим нашу первую страничку:\r\n\r\n<!DOCTYPE html> <html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт </title>\r\n</head>\r\n<body>\r\n<p align=\"center\">Привет мир!!!</p>\r\n<br>\r\n<p align=\"justify\">\r\nМеня зовут Карлсон! Я в меру упитанный мужчина - это моя первая страничка!\r\nЗдесь я хочу найти себе новых друзей, для того чтобы вместе гулять по крышам! Я\r\nочень очень сильно люблю варениѐ!!! С нетерпением буду ждать Вашего\r\nприглашения на чай. Прилечу!!\r\n</p>\r\n</body>\r\n</html>\r\n\r\nПродолжим работу с кодом в выбранном текстовом редакторе, например Блокноте или WordPad (не путать с Microsoft Word!).\r\nСнова запускаем Блокнот- жмем кнопку Пуск -> Все программы -> Стандартные -> Блокнот\r\nили Пуск -> Все программы -> Стандартные ->WordPad\r\nТеперь выделите код написанный выше и скопируйте его в Блокнот.(Копирование и вставка текста элементарные известные действия)\r\nТеперь выбираем в меню Блокнота : Файл - > Сохранить как ...\r\nСохраняем в ту же папку  sites на диске С. \r\nСохранять в \"Мои документы\" или \"Рабочий стол\" не надо! \r\nЗатем вводим имя файла, под которым мы сохраним нашу страничку например page(здесь можно вставить либо номер либо название).html ,  жмем кнопку \"Сохранить\". (обратите внимание на точку между page и html).Сохраняем в ту же папку  sites на диске С.\r\nРасширение файла .html - показывает, что данный файл является интернет-страницей.\r\nТеперь найдите в вашей папке sites  сохраненный файл page.html вашей интернет страницы.\r\nТеперь запустите файл page.html, нажав мышкой по файлу 2 раза.\r\nУ Вас запуститься Ваш браузер посмотрите что у Вас получилось.\r\nЗапоминаем!\r\nКоманды, которые пишутся между скобками < > называются тегами.\r\nТеги бывают парные и не парные. Парные теги например <head> и </head> Один тег является открывающим <head>, а другой тег является закрывающим </head> . Теги внутри себя могут иметь свои атрибуты.\r\nТег <html> говорит компьютеру, что начитается html-страница. Тег </html>  что html-страница закончилась. Таким образом тег <html> будет всегда первым тегом на странице, а тег </html> самым последним.  Все остальное пишется между этими тегами.\r\nМежду тегами <head> и </head> вставляются теги <title> и </title>. \r\nМежду тегами <title> и </title> пишется название страницы. Текст написанный между этими тегами будет отображаться в названии окна Вашего браузера. Между тегами <body> и </body> пишется непосредственно содержимое интернет страницы (иначе говоря контент страницы). Все что Вы напишите - будет на Вашей странице.\r\nПробелы в тегах после < и перед > ставить не надо! Это ошибка!\r\nПримечание: В нормативную документацию по html (сейчас уже пятая версия-HTML-5) вносились со временем изменения..\r\nРяд тегов были признаны не актуальными или не парными, но они до сих пор как и прежде обрабатываются браузерами.', 'photos/2025/$m/14/bg-showcase-2.jpg', '2025-07-14 10:22:24.405569', '2025-07-14 10:22:24.405612', 1, 1),
(4, 'Форматирование и дизайн страницы', 'phormatirovanie', 'В наборе тегов html языка имеется шесть типов заголовков:\r\n<h1> Привет мир!!! </h1>\r\n<h2> Привет мир!!! </h2>, <h3>...</h3>,<h4>...</h4>,<h5>...</h5>,<h6>...</h6>\r\nЧем меньше цифра тем больше размер букв в заголовке.\r\nА что если нам надо выделить весь текст? Для этого можно использовать тег <font> в переводе на русский - \"шрифт\".. Тег <font> помимо прочих\r\nатрибутов, имеет атрибут size - размер. Пишется и выглядит это так:\r\n<font size=\"+2\">Привет мир!!!</font>\r\nДобавим эти теги на нашу страницу:\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body>\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<font size=\"+2\">Меня зовут Карлсон! Я в меру упитанный мужчина - это моя первая\r\nстраничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по\r\nкрышам! Я очень сильно люблю <font size=\"+2\">вареньѐ!!!</font> С нетерпеньем\r\nбуду ждать Вашего приглашения на чай. Прилечу!!</font>\r\n</p>\r\n</body>\r\n</html>\r\n\r\nВнесите изменения на свою страницу и посмотрите результат.\r\n\r\nДля придания страничке красивого вида не обойтись без палитры с красками.\r\nОдин и тот же цвет можно задать двумя способами:\r\nиспользуя шестнадцатеричное значение цвета RGB - например #0000ff - голубой цвет, или #ffff00 - желтый цвет либо используя название цвета-blue (голубой),\r\nyellow (желтый).\r\n\r\nРаскрашиваем страницу.\r\nАтрибут тега <body> bgcolor и его значение задает цвет фона всей страницы:\r\n<body bgcolor=\"#0000ff\"> залили все голубым цветом.\r\nВнимание! 00 это цифры ноль, а не буквы ОО. Также, нельзя писать слитно без пробела <bodybgcolor=\"#0000FF\">.\r\nИтак пробуем открываем наш файл page.html в любом редакторе и изменяем код с дальнейшим сохранением:\r\n\r\n!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<font size=\"+2\">Меня зовут Карлсон! Я в меру упитанный мужчина - это моя первая\r\nстраничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по\r\nкрышам! Я очень сильно люблю <font size=\"+3\">вареньѐ!!!</font> С нетерпеньем\r\nбуду ждать Вашего приглашения на чай. Прилечу!!</font>\r\n</p>\r\n</body>\r\n</html>\r\nОткрываем файл в браузере. Получили голубой фон страницы и желтый цвет текста.\r\n\r\nМы уже знакомы с тегом <font> у него есть еще один атрибут - color. Так вот, если\r\nЕсли вы хотите в произвольном месте текста использовать цвет, отличный от цвета по умолчанию, то надо заключить нужный вам текст между тегами <font> и </font> и указать в теге требуемый цвет:\r\n<font color=\"#ffff00\">Привет мир!!!</font> - То цвет шрифта станет желтым.\r\nА можно так:\r\n<font color=\"yellow\">Привет мир!!!</font> - Будет тоже самое.. если изменить:\r\n<font color=\"red\">Привет мир!!!</font>- будет красным\r\n\r\nДобавьте на страницу следующее\r\n<font color=\"red\">С нетерпеньем буду ждать Вашего приглашения на чай</font>\r\n\r\nКод вашей странице теперь будет такой :\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<font size=\"+2\">Меня зовут Карлсон! Я в меру упитанный мужчина - это моя первая\r\nстраничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по\r\nкрышам! Я очень сильно люблю <font size=\"+3\">гулять!</font><font color=\"red\">С нетерпеньем буду ждать Вашего приглашения на чай.</font> Прилечу!!</font>\r\n</p>\r\n</body>\r\n</html>\r\nСмотрим на результат-папка site. Тег <br> используют для переноса строки\r\n\r\nСтиль текста:\r\nЗдесь все достаточно просто..\r\nИтак, новые теги:\r\n<b> </b> - Полужирный текст\r\n<i> </i> - Наклонный текст\r\n<u> </u> - Подчеркнутый текст\r\n<strike> </strike> - Перечеркнутый\r\n<tt> </tt> - моноширинный шрифт\r\n<sup> </sup> - Верхний индекс\r\n<sub> </sub> - Нижний индекс\r\nНу думаю понятно.. текст заключѐнный между этими открывающими и закрывающими тегами приобретѐт нужный нам стиль.\r\nШрифт:\r\nДля того чтобы изменить шрифт документа необходимо дать указание браузеру, что мол от сюда до сюда показывать текст таким шрифтом. Для этого используем всѐ тот же тег <font> и его атрибут face - лицо\r\nПишется так:\r\n<font face=\"arial\">Эта строчка будет написана с помощью шрифта Arial</font>\r\nС переченем названий и образцов шрифтов легко ознакомиться в интернете.\r\n\r\nОткройте любой редактор впишите код и сохраните как и ранее в папку sites.\r\nДайте другое имя например page2.html:\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Использование различных шрифтов</title>\r\n</head>\r\n<body>\r\n<font face=\"arial\">Мало кто знает, как много надо знать для того, что бы знать, как мало мы знаем.</font>\r\n<br>\r\n<font face=\"times new roman\">Мало кто знает, как много надо знать для того, что бы знать, как мало мы знаем.</font>\r\n<br>\r\n<font face=\"comic sans ms\">Мало кто знает, как много надо знать для того, что бы\r\nзнать, как мало мы знаем.</font>\r\n<br>\r\n</body>\r\n</html>\r\nОткройте после сохранения(сохранить в формате utf-8) файл page2.html и посмотрите на результат\r\n\r\nПредварительно отформатированный текст:\r\n\r\nЕсли Вы обратили внимание, а если не обратили то знайте, что в браузерах текст набранный с помощью текстовых редакторов проходит \"обработку\" перед выводом его на экран компьютера.Так в набранном Вами тексте удаляются все переносы строк и лишние пробелы, пробелов между словами или просто символами может быть не более одного.\r\nТег <pre>, текст заключѐнный в данный тег выводится браузерами на экран в\r\nтом виде в котором он был набран, т.е. без изменения и корректировки.', 'photos/2025/$m/14/vera.jpg', '2025-07-14 10:40:18.903140', '2025-07-14 10:40:18.903209', 1, 1),
(5, 'Вставка изображений', 'vstavka', 'Вставляем на сайт картинку(ФОТО):\r\nДопустим вы решили вставить на страницу картинку как в левом углу :\r\nСначала вам нужно сохранить эту(или любую другую) картинку у себя на компьютере. Для этого наведите курсор мышки на картинку и нажмите правую кнопку мышки. Выберите \"Сохранить рисунок как...\" Укажите папку sites( ту же, где находится страничка, которую мы делаем - page.html) Имя файла картинки - можно любое название например- karloson , jpg.-расширение файла обязательно-в нашем примере - karloson.jpg(Вставляем в строку \"имя файла\" karloson.jpg, нажимаем \"сохранить\"). Для вставки на страницу картинки - используется тег <img>. img это он английского слова image...изображение, картинка.В качестве параметра для этого тега, используется название картинки.В нашем случае для вставки картинки вставляем karloson.jpg в код страницы, в то место куда мы хотим вставить картинку, следующий код :\r\n<img src= kaploson.jpg> или более грамотно писать вот так <imgsrc=\"karloson.jpg\"> , хотя код выше тоже будет работать,через параметр src указывается имя файла-картинки, src от английскогого слова source - ресурс, источник.\r\nTеги <br> вставлены чтобы расположить картинку на несколько строк ниже текста.\r\nЖелательно в параметрах картинки указать ее размеры. Для этого используется параметр width (ширина картинки) wheight (высота картинки) (также будьте внимательны в написании. Не with, не witdh, не heihgt)\r\nТ.е. например вот так :\r\n<img src=\"karloson.jpg\" width=\"258\" height=\"146\">\r\nразмеры картинки указываются в пикселях. Если вы хотите, чтобы при наведении мышки на картинку отображался какой-то текст, то это делается с помощью параметра alt например вот так :\r\n<img src=\"karloson.jpg\" width=\"358\" height=\"246\" alt=\"Это я Карлосон\">\r\nДля расположения изображения по центру используем тег <center>...</center>:\r\n<center><img src=\"karloson.jpg\" width=\"358\" height=\"246\" alt=\"Это я Карлосон\"></center>\r\nBнесите изменения в код. Таким образом код нашей страницы будет такой :\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<font size=\"+2\">Меня зовут Карлсон! Я в меру упитанный мужчина - это моя первая\r\nстраничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по\r\nкрышам! Я очень сильно люблю <font size=\"+3\">гулять!</font><font color=\"red\">С нетерпеньем буду ждать Вашего приглашения на чай.</font> Прилечу!!<font><br><br>\r\n<center><img src=\"karloson.jpg\" width=\"358\" height=\"246\" alt=\"Это я Карлосон\"></center>\r\n</p>\r\n</body>\r\n</html>\r\nПосмотрите на вашу страницу-папка sites.\r\nЕсли у вас вместо картинки показывается \"крестик\",то значит вы допустили одну из распространенных ошибок:\r\n- сохранили файл не в той же папке, где находится html-файл.\r\n- сохранили файл под другим именем, например не верно указали расширение файла. Должно быть jpg\r\n- допустили ошибку в параметре, написав например scr= вместо src=\r\n- не верно указали имя файла или расширение после src=', 'photos/2025/$m/14/karloson.jpg', '2025-07-14 10:43:38.817209', '2025-07-14 10:43:38.817253', 1, 1),
(6, 'Основные теги для изображений', 'osnovnie-tegi-dlya-photo', 'Откройте пост для чтения.Нажмите на рисунок слева. Это результат по нашей странице.\r\nАтрибуты тега <img>:\r\nКак и другие теги <img> тоже имеет свои атрибуты.. уже знакомый нам атрибут align\r\n\"выравнивание\" применим и к данному тегу\r\n<img src=\"foto.jpg\" align=\"left\"> - фото слева от текста\r\n<img src=\"foto.jpg\" align=\"right\"> - фото справа от текста\r\n<img src=\"foto.jpg\" align=\"top\"> - текст выше фото\r\n<img src=\"foto.jpg\" align=\"bottom\"> - текст ниже фото\r\n<img src=\"foto.jpg\" align=\"middle\"> - ну и соответственно текст посередине\r\n<img src=\"foto.jpg\" vspace=\"15\"> - Атрибут vspace задаѐт расстояние по вертикали от рисунка до текста, в данном случае мы задали расстояние в 15 пикселей\r\n<img src=\"foto.jpg\" hspace=\"25\"> - Расстояние по горизонтали соответственно\r\n<img src=\"foto.jpg\" width=\"180\"> - Ширина непосредственно самого изображения\r\n<img src=\"foto.jpg\" height=\"240\"> - Высота изображения. Если атрибуты width и height не использовать, то ширина и высота изображения по умолчанию будет равна реальным еѐ размерам, без каких либо искажений.\r\n<img src=\"foto.jpg\" border=\"5\">- Бордюр, рамка вокруг изображения и еѐ толщина в\r\nпикселях.\r\n<img src=\"foto.jpg\" border=\"5\" bordercolor=\"#008000 \"> - bordercolor - это цвет рамки.', 'photos/2025/$m/14/page1.png', '2025-07-14 10:47:56.244877', '2025-07-14 10:47:56.244924', 1, 1),
(7, 'Ссылки', 'ssilki', 'В этой главе постараюсь подробно рассказать о\r\nтом как прописать ссылки, а так же посвятить в тонкости дела по работе с ними.\r\nЛирическое отступление:\r\n\r\nWeb-программист - это такой специалист, деятельность которого тесно связана с «всемирной паутиной». Его задача – это создание ресурсов(сайтов), которые будут жить и развиваться в сети. Без помощи этого профессионала невозможно реализовать ни один интернет-проект.\r\n\r\nЧтобы браузер смог найти документ(страницу, ресунок и т.д.) ему необходимо знать\r\nточное название документа, путь к документу, и место куда его принести, точнее где его открыть. Давайте в нашу папку sites скачаем несколько изображений с интернета. У меня в папке уже есть изображения которые я использую в этом сайте.\r\nВы выберите несколько понравившихся и скачайте.\r\nНа данный момент с помощью блокнота мы создали только один HTML документ у меня он с именем page.html. В этом документе мы попробуем создать ссылку на другой документ, которого у нас еще нет.. Но прежде чем на него ссылаться, его нужно создать, давайте создадим этот- другой документ:\r\n1. Открываем блокнот.\r\n2. Пишем код на html языке- к примеру страничку с рядом фотографий:\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Наши изображения из папки sites!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<font size=\"+2\">\r\nПоместим здесь несколько наших\r\n<font size=\"+3\">изображений!</font> Мы их сами скачали сюда !<font><br><br>\r\n<center><img src=\"karloson.jpg\" width=\"358\" height=\"246\"></center>\r\n<center><img src=\"vera.jpg\" width=\"358\" height=\"246\"></center>\r\n</p>\r\n</body>\r\n</html>\r\n\r\n3. Сохраняем его как primer.html страничку в ту же рабочую папку, где уже есть созданный нами первый документ и изображения. Теперь я знаю, что у Вас два html документа page.html и primer.html и что теперь у Вас есть минимальный набор для дальнейшего обучения.\r\nТекстовые ссылки:\r\nЗнакомимся, тег <a> (от anchor- якорь), в него можно заключить текст или рисунок, которые станут ссылкой на те или иные документы. Атрибут тега <a> href задаѐт имя и путь к документу на который указывает ссылка.\r\nВсѐ вместе пишется так:\r\n<a href=\"primer.html\">Меня зовут Карлсон!</a>\r\nКак Вы наверное поняли primer.html это имя нашего второго html документа, а надпись \"Меня зовут Карлсон!\" это кусочек текста из файла page.html.Откройте\r\nс помощью блокнота файл page.html и замените код на этот(откорректируйте)\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<a href=\"primer.html\"><font size=\"+2\", font color=\"red\">Меня зовут Карлсон!</font></a><font size=\"+2\"> Я в меру упитанный мужчина - это моя первая\r\nстраничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по\r\nкрышам! Я очень сильно люблю <font size=\"+3\">гулять!</font><font color=\"red\">С нетерпеньем буду ждать Вашего приглашения на чай.</font> Прилечу!!<font><br><br>\r\n<center><img src=\"karloson.jpg\" width=\"358\" height=\"246\"></center>\r\n</p>\r\n</body>\r\n</html>\r\n\r\nСтрока \"Меня зовут Карлсон!\"является ссылкой по которой мы переходим к файлу \"primer.html\". С помощью тега <font> мы задали сами цвет размер текста(<font size=\"+2\", font color=\"red\">).\r\nНо по умолчанию принято что ссылки выделяются цветом, синеньким - ссылка, а\r\nкрасненьким - уже посещенная ссылка, эти цвета можно изменить с помощью уже хорошо известного нам открывающего тега < body > и его атрибутов.\r\nlink - цвет ссылки.\r\nalink - цвет нажатой, активной ссылки.\r\nvlink - цвет посещенной ссылки.\r\nПишется так:\r\n<body link=\"#008000\" alink=\"# ff0000 \" vlink=\"# ffff00\">\r\nПо аналогии с рисунками тега <img>, путь ссылки к открываемому документу прописывается теми же способами:\r\n<a href=\"primer.html\">Меня зовут Карлсон! </a> - Такая запись\r\nподразумевает, что в директории(папке), где расположен наш page.html документ есть файл primer.html. на который переходим по ссылке.\r\n<a href=\" stranica/primer.html\">Меня зовут Карлсон! </a> - Такая запись\r\nподразумевает, что в директории(папке), где расположен наш page.html документ есть папка stranica в которой расположен файл primer.html.\r\nТакая запись:\r\n<a href=\"http://www.site.ru/primer.html\">Меня зовут Карлсон!</a> - что документ primer.html расположен на сайте www.site.ru\r\n\r\nСсылкой может являться не только текст, но и рисунок.. Здесь принцип такой же как и в текстовой ссылке, просто вместо текста мы заключаем рисунок который хотим сделать ссылкой.\r\nВот так:\r\n\r\n<a href=\"primer.html\"><img src=\"karloson.jpg\" width=\"358\" height=\"246\"\"></a>\r\n\r\nДавайте вставим в код файла page.html эту строку теперь выглядеть будет так:\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<a href=\"primer.html\"><font size=\"+2\", font color=\"red\">Меня зовут Карлсон!</font></a><font size=\"+2\"> Я в меру упитанный мужчина - это моя первая\r\nстраничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по\r\nкрышам! Я очень сильно люблю <font size=\"+3\">гулять!</font><font color=\"red\">С нетерпеньем буду ждать Вашего приглашения на чай.</font> Прилечу!!<font><br><br>\r\n<center><a href=\"primer.html\"><img src=\"karloson.jpg\" width=\"358\" height=\"246\"\"></a></center>\r\n</p>\r\n</body>\r\n</html>\r\n\r\nТеперь картинка с Карлсоном тоже стала ссылкой на страницу primer.html. При нажатии курсором на нее мы переходим на этот файл как и по тестовой ссылке-(Строка \"Меня зовут Карлсон!\")\r\n\r\nСсылка на e-mail:\r\nДля того что бы сделать текст или рисунок ссылкой на e-mail - почтовый ящик его нужно заключить в тег <a>, но не простой, а с использованием mailto\r\nПишем например так:\r\n<a href=\"mailto:karlson@kruha.ru\"> Напишите мне письмо.. </a>\r\nЭта непривычная запись будет говорить что, кликнув по тексту ссылке \"Напишите мне письмо..\" посетитель сайта попадет в свою почтовую программу(например mail.ru), которая выдаст ему бланк для отправки письма, где в строчке Кому: уже будет указан нужный нам почтовый ящик karlson@kruha.ru.\r\nДавайте расположим строку\" Поместим здесь несколько наших изображений! Мы их сами скачали туда !\" в файле primer.html по середине через известный нам тег-\r\n<center>. Откроем через с помощью блокнота этот файл и изменим немного код:\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Изображения</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Наши изображения из папки sites!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<font size=\"+2\">\r\n<center>Поместим здесь несколько наших\r\n<font size=\"+3\">изображений!</font> Мы их сами скачали сюда !</center><br><br>\r\n<center><img src=\"karloson.jpg\" width=\"358\" height=\"246\"></center>\r\n<center><img src=\"vera.jpg\" width=\"358\" height=\"246\"></center>\r\n</p>\r\n</body>\r\n</html>\r\nСохраним изменения и откроем файл. Так выглядит намного лучше.\r\nЭто лишь часть того что может Html. Если Вас это заинтересовало и у Вас все получилось можете смело перейти к полному изучению этого языка гиперразметки. На страницах интернета много учебников для начинающих, информация в которых поможет Вам глубже все понять и попробовать.', 'photos/2025/$m/14/bg-showcase-1.jpg', '2025-07-14 10:52:05.587535', '2025-07-14 10:52:05.587589', 1, 1),
(8, 'Основы CSS', 'osnovi_css', 'Аббревиатура CSS расшифровывается как Cascading Style Sheets, что в переводе означает «каскадные таблицы стилей». Это язык разметки, используемый для визуального оформления страниц веб-сайтов. Практически любые «внешние проявления» сайта создаются с помощью CSS. Это стиль его страниц. Объекты, расположенные на странице, размещаются с помощью HTML. А вот CSS отвечает за то, как эти объекты выглядят. Их размер, цвет, фоновое изображение, степень прозрачности, расположение относительно других элементов, поведение при наведении курсора, визуальное изменение кнопок при нажатии и т.п. Достаточно ознакомиться с простейшими правилами CSS, и можно легко собрать вполне симпатичный сайт со всем необходимым контентом. Правила объявлений настолько просты, что их можно описать в одном предложении. Сначала пишется селектор, который выбирает конкретный элемент на странице, после фигурных скобок пишутся свойства со значениями после двоеточия, а сами свойства отделяются друг от друга точкой с запятой.\r\n«Простота» обеспечивается за счет понятного синтаксиса. Синтаксис CSS в отдельном файле в соответствующем формате (.css) выглядит так:\r\n\r\nселектор {\r\nсвойство: значение;\r\nсвойство:значение;\r\n}\r\n\r\nСелектор – это ссылка на элемент в HTML, над которым будет вестись работа (оформление).\r\n\r\nСвойство – определенная характеристика элемента, которую нужно изменить. Например, размер или цвет.\r\n\r\nЗначение – цифровое или текстовое обозначение для выбранного свойства.', 'photos/2025/$m/14/klipartz.com.png', '2025-07-14 10:56:21.037200', '2025-07-14 10:56:21.037244', 1, 2),
(9, 'Использование CSS в HTML документах', 'ispolzovanie', 'CSS довольно просто использовать в HTML документах. Его можно:\r\n1. Прописать стили в самом документе, используя тег <style>:\r\n\r\nДавайте откроем с помощью редактора наш файл page.html и посмотрим на код:\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт</title>\r\n</head>\r\n<body bgcolor=\"#0000FF\" text=\"#FFFF00\">\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<a href=\"primer.html\"><font size=\"+2\", font color=\"red\">Меня зовут Карлсон!</font></a><font size=\"+2\"> Я в меру упитанный мужчина - это моя первая страничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по крышам! Я очень сильно люблю <font size=\"+3\">гулять!</font><font color=\"red\">С нетерпеньем буду ждать Вашего приглашения на чай.</font> Прилечу!!<font><br><br>\r\n<center><a href=\"primer.html\"><img src=\"karloson.jpg\" width=\"358\" height=\"246\"\"></a></center>\r\n</p>\r\n</body>\r\n</html>\r\n\r\nДавайте теперь внесем изменения в код- вырезаем старый и вставляем новый- немного откорректированный:\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Страница с применением стилей</title>\r\n<style type=\"text/css\">\r\nh2 {color: red; font-style: italic; font-size: 30px}\r\nbody {background-color: yellow; text-align: center; color: green; font-style: italic; font-size: 20px;}\r\n</style>\r\n</head>\r\n<body>\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<a href=\"primer.html\">Меня зовут Карлсон!</a> Я в меру упитанный мужчина - это моя первая страничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по крышам! Я очень сильно люблю гулять! С не терпеньем буду ждать Вашего приглашения на чай.Прилечу!!!<br><br>\r\n<center><a href=\"primer.html\"><img src=\"karloson.jpg\" width=\"358\" height=\"246\"\"></a></center>\r\n</p>\r\n</body>\r\n</html>\r\nСохраняем код изменяя имя файла(например на page1.html) чтобы иметь возможность для сравнения двух наших файлов page.html и page1.html.\r\nКак вы заметили мы в содержимое тега <style>...</style> вставили фрагмент наших стилей:\r\n<style type=\"text/css\">\r\nh2 {color: red; font-style: italic; font-size: 30px}\r\nbody {background-color: yellow; text-align: center; color: green; font-style: italic; font-size: 20px;}\r\n</style> т.е для тега <h2> задали цвет, вид шрифта и его размер, для тега <body> цвет фона страницы, размещение текста по центру, его цвет, размер отступления, вид шрифта и его размер.\r\nПри этом упростили и улучшили код, убрав правила стилей из блока <body>.../<body>. Но писать стили на каждой странице, к каждому тегу утомительно. Можно легко запутаться. Ведь в случае изменения значений стилей, приходиться находить их и корректировать на всех страницах. Гораздо удобнее прописать все правила в отдельном файле. Тогда вносить изменения придется только в одном файле\r\n\r\n2. Подключить как внешний CSS файл к документу. Для этого достаточно прописать тег <link rel=\"stylesheet\" href=\"путь/до/файла.css\"> в теге <head> и все правила стилей прописать в этом внешнем файле. Это наиболее распространенный способ подключения таблиц стилей к документу, когда внешнее оформление страниц выносится в отдельный внешний CSS файл.\r\nОткроем редактор(блокнот) и наберем свой набор правил стилей:\r\nh2 {color: red;\r\nfont-style: italic;\r\nfont-size: 30px}\r\n\r\nbody {background-color: yellow;\r\ntext-align: center;\r\ncolor: green;\r\nfont-style: italic;\r\nfont-size: 20px;}\r\nСохраняем в той же папке с именем style и расширением через точку- .css (style.css). Тип файла оставляем как текстовый. Откроем с помощью редактора файл page1.html уберем стили и подключим свой внешний файл стилей style.css. Присоединение внешних таблиц к html - документу осуществляется тегом link. При этом его атрибут type должен быть установлен в значении \"text/css\":\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Пример подключения таблицы стилей</title>\r\n<link rel = \"stylesheet\" type=\"text/css\" href = \"style.css\"\r\n</head>\r\n<body>\r\n<center><h2>Привет мир!!!</h2></center>\r\n<br>\r\n<p align=\"justify\">\r\n<a href=\"primer.html\">Меня зовут Карлсон!</a> Я в меру упитанный мужчина - это моя первая страничка! Здесь я хочу найти себе новых друзей, для того чтобы вместе гулять по крышам! Я очень сильно люблю гулять! С не терпеньем буду ждать Вашего приглашения на чай.Прилечу!!!<br><br>\r\n<center><a href=\"primer.html\"><img src=\"karloson.jpg\" width=\"358\" height=\"246\"\"></a></center>\r\n</p>\r\n</body>\r\n</html>\r\n\r\nСохраняем как и раньше меняя имя файла, например, на page3.html. Как видите получаем тоже самое что и при открытии файла page1.html. Нужно иметь ввиду что при изменении стилей по ходу составления кода каждый последующий тег style или link имеет приоритет над предыдущим.', 'photos/2025/$m/14/htmlcss.jpg', '2025-07-14 10:59:39.047183', '2025-07-14 10:59:39.047239', 1, 2),
(10, 'Форматирование документа средствами CSS3', 'phormatirovanie-css', 'Применение тегов\r\nВы знаете, что такое параграф.. это такой кусочек текста, одно или несколько\r\nпредложений, который в книгах обычно печатается с новой строки. Для того чтобы на странице сайта разбить текст на параграфы, необходимо\r\nвоспользоваться тегом <p> - собственно параграф. Параграф имеет атрибут align \"выравнивание\" который в свою очередь может быть равен\r\nтому ли иному значению. Например с помощью параграфа можно расположить текст по центру:\r\n<p align=\"center\">Привет мир!!!</p>\r\nПо левому краю:\r\n<p align=\"left\">Привет мир!!!</p>\r\nПо правому краю:\r\n<p align=\"right\">Привет мир!!!</p>\r\nИли же обоим краям документа:\r\n<p align=\"justify\">Привет мир!!! - здесь нужен текст по длиней чтобы эффект был\r\nхорошо виден при открытии документа</p>\r\nПо умолчанию Ваш текст выравнивается браузером по левому краю, так что если Вам так\r\nи надо атрибут align=\"left\" для параграфа можно не указывать. Тег <p> подразумевает в себе перенос строки, если это Вам не нужно, используйте вместо\r\nтега <p> тег <div> данный тег является альтернативой тегу <p> пишится так:\r\n<div align=\"center\">Привет мир!!!</div>\r\n<div align=\"left\">Привет мир!!!</div>\r\n<div align=\"right\">Привет мир!!!</div>\r\n<div align=\"justify\">Привет мир!!!</div>\r\nДавайте слегка изменим нашу первую страничку:\r\n\r\n<!DOCTYPE html> <html lang=\"ru\">\r\n<head>\r\n<title>Мой первый сайт </title>\r\n</head>\r\n<body>\r\n<p align=\"center\">Привет мир!!!</p>\r\n<br>\r\n<p align=\"justify\">\r\nМеня зовут Карлсон! Я в меру упитанный мужчина - это моя первая страничка!\r\nЗдесь я хочу найти себе новых друзей, для того чтобы вместе гулять по крышам! Я\r\nочень очень сильно люблю варениѐ!!! С нетерпением буду ждать Вашего\r\nприглашения на чай. Прилечу!!\r\n</p>\r\n</body>\r\n</html>\r\n\r\nПродолжим работу с кодом в выбранном текстовом редакторе, например Блокноте или WordPad (не путать с Microsoft Word!).\r\nСнова запускаем Блокнот- жмем кнопку Пуск -> Все программы -> Стандартные -> Блокнот\r\nили Пуск -> Все программы -> Стандартные ->WordPad\r\nТеперь выделите код написанный выше и скопируйте его в Блокнот.(Копирование и вставка текста элементарные известные действия)\r\nТеперь выбираем в меню Блокнота : Файл - > Сохранить как ...\r\nСохраняем в ту же папку  sites на диске С. \r\nСохранять в \"Мои документы\" или \"Рабочий стол\" не надо! \r\nЗатем вводим имя файла, под которым мы сохраним нашу страничку например page(здесь можно вставить либо номер либо название).html ,  жмем кнопку \"Сохранить\". (обратите внимание на точку между page и html).Сохраняем в ту же папку  sites на диске С.\r\nРасширение файла .html - показывает, что данный файл является интернет-страницей.\r\nТеперь найдите в вашей папке sites  сохраненный файл page.html вашей интернет страницы.\r\nТеперь запустите файл page.html, нажав мышкой по файлу 2 раза.\r\nУ Вас запуститься Ваш браузер посмотрите что у Вас получилось.\r\nЗапоминаем!\r\nКоманды, которые пишутся между скобками < > называются тегами.\r\nТеги бывают парные и не парные. Парные теги например <head> и </head> Один тег является открывающим <head>, а другой тег является закрывающим </head> . Теги внутри себя могут иметь свои атрибуты.\r\nТег <html> говорит компьютеру, что начитается html-страница. Тег </html>  что html-страница закончилась. Таким образом тег <html> будет всегда первым тегом на странице, а тег </html> самым последним.  Все остальное пишется между этими тегами.\r\nМежду тегами <head> и </head> вставляются теги <title> и </title>. \r\nМежду тегами <title> и </title> пишется название страницы. Текст написанный между этими тегами будет отображаться в названии окна Вашего браузера. Между тегами <body> и </body> пишется непосредственно содержимое интернет страницы (иначе говоря контент страницы). Все что Вы напишите - будет на Вашей странице.\r\nПробелы в тегах после < и перед > ставить не надо! Это ошибка!\r\nПримечание: В нормативную документацию по html (сейчас уже пятая версия-HTML-5) вносились со временем изменения..\r\nРяд тегов были признаны не актуальными или не парными, но они до сих пор как и прежде обрабатываются браузерами.', 'photos/2025/$m/14/otstup.jpg', '2025-07-14 11:05:14.298267', '2025-07-14 11:05:14.298333', 1, 2),
(11, 'Технологии визуального представления документа. Блоки и контейнеры', 'bloki-konteineri', 'Каждый элемент в CSS заключён в блок, и понимание поведения этих блоков — это ключ к умению задавать раскладку с помощью CSS, то есть выстраивать одни элементы относительно других элементов, причем если в html это зависит от их задания согласно html-кода, то в CSS3 визуальное расположение элементов на странице может быть независимо от других блоков и даже перекрывать их.\r\nВ CSS3 мы, говоря упрощённо, имеем два типа элементов — блочные и строчные.\r\nЕсли элемент определён как блочный, то он будет вести себя следующим образом:\r\nНачнётся с новой строки.\r\nБудет расширяться вдоль строки таким образом, чтобы заполнить всё пространство, доступное в её контейнере. В большинстве случаев это означает, что блок станет такой же ширины, как и его контейнер, заполняя 100% доступного пространства.\r\nБудут применяться свойства width и height.\r\nВнешние и внутренние отступы, рамка будут отодвигать от него другие элементы.\r\nКак примеры элемнты: <div>, <h1>, <p> и др.\r\nПолностью блочная модель в CSS применяется к блочным элементам, строчные элементы используют не все свойства, определённые блочной моделью.\r\n\r\nЕсли элемент имеет тип отображения inline (строчный), то:\r\n\r\nОн не будет начинаться с новой строки.\r\nСвойства width и height не будут применяться.\r\nВертикальные внешние и внутренние отступы, рамки будут применяться, но не будут отодвигать другие строчные элементы.\r\nГоризонтальные внешние и внутренние отступы, рамки будут применяться и будут отодвигать другие строчные элементы.\r\nЭлемент <a>, используемый для ссылок, <span>, <em> и <strong> — всё это примеры по умолчанию строчных элементов.\r\n\r\nСоставляя блочный элемент в CSS мы имеем:\r\n\r\nСодержимое: область, где отображается ваш контент, размер которой можно изменить с помощью таких свойств, как width и height.\r\nВнутренний отступ: отступы располагаются вокруг содержимого в виде пустого пространства; их размер контролируется с помощью padding и связанных свойств.\r\nРамка: рамка оборачивает содержимое и внутренние отступы. Её размер и стиль можно контролировать с помощью border и связанных свойств.\r\nВнешний отступ: внешний слой, заключающий в себе содержимое, внутренний отступ и рамки, представляет собой пространство между текущим и другими элементами. Его размер контролируется с помощью margin и связанных свойств.\r\nВ стандартной блочной модели, если указать элементу атрибуты width и height, это определит ширину и высоту содержимого. Любые отступы и рамки затем добавляются к этой ширине и высоте для получения общего размера элемента. Укажем основному элементу <body>(блоку с содержимым страницы) свойства и атрибуты для определения ширины и высоты:\r\nbody{\r\nwidth: 1420px;\r\nheight: 610px;\r\nmargin: 10px;\r\npadding: 25px;\r\nborder: 5px solid black;\r\n}\r\n\r\nОткройте с помощью редактора файл page5.html и добавьте этот фрагмент стилей. Код примет вид:\r\n<!DOCTYPE html>\r\n<html lang=\"ru\">\r\n<head>\r\n<title>Блоки и контейнеры</title>\r\n<style type=\"text/css\">\r\nbody{\r\nwidth: 1420px;\r\nheight: 610px;\r\nmargin: 10px;\r\npadding: 25px;\r\nborder: 5px solid black;\r\n}\r\nspan h2{border:5px solid red; /* красная рамка, span-для перевода в строковый вид*/\r\nmargin: 20px;color: red; background-color: yellow;\r\nfont-style: italic; font-size: 30px\r\n}\r\ndiv{\r\nborder:5px solid green; /* зеленая рамка */\r\nbackground-color: yellow; text-align: center; color: green; margin: 20px; font-style: italic;\r\nfont-size: 20px;\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n<center><span><h2>Привет мир!!!</h2></span></center>\r\n<br>\r\n<div>\r\n<p align=\"justify\">\r\n<a href=\"primer.html\">Меня зовут Карлсон!</a> Я в меру упитанный мужчина - это моя первая страничка! Здесь я хочу найти себе новых друзей,\r\nдля того чтобы вместе гулять по крышам! Я очень сильно люблю гулять! С не терпеньем буду ждать Вашего\r\nприглашения на чай.Прилечу!!!<br><br>\r\n<center><a href=\"primer.html\"><img src=\"karloson.jpg\" width=\"358\" height=\"246\"\"></a></center>\r\n</p>\r\n</div>\r\n</body>\r\n</html>\r\nСохраните под именем page6.html. Как видите мы получили блок с рамкой.\r\nПространство, занимаемое нашим блоком на самом деле будет равно 1480px в ширину (1420 + 25 + 25 + 5 + 5) и 670px в высоту (610 + 25 + 25 + 5 + 5), поскольку отступы и рамки добавляются к размерам поля содержимого.', 'photos/2025/$m/14/bloki.png', '2025-07-14 11:07:29.810461', '2025-07-14 11:07:29.810510', 1, 2),
(12, 'Программное обеспечение. Установка  Python', 'ustanovka', 'В этом разделе  будет идти речь о том, как писать программы на языке\r\nпрограммирования, который называется Python (правильно читается как\r\nПайтон, но обычно название языка читают как питон, что тоже вполне\r\nприемлемо). Программный код на python можно набирать хоть в текстовом\r\nредакторе(Блокнот, WordPad и т.д). \r\nДля выполнения же набранного программного кода понадобится специальная программа, которая называется интерпретатором. \r\nДля удобства  используется  интегрированная среда разработки, которая, кроме прочего, включает в себя как редактор программных кодов, так и интерпретатор.\r\nНапример Visual Studio Code. Visual Studio Code (VS Code) — это бесплатный, легко устанавливаемый редактор исходного кода  в который встроен терминал . Его разработал Microsoft для всех популярных операционных систем: Windows, Linux и macOS. Можно также использовать бесплатный редактор PyCharm и др.  \r\nДля работы с Python  находим в интернете и скачиваем установщик редактора Visual Studio Code. Запускаем установщик и следуем инструкциям. Здесь всё стандартно, как с установкой любой программы: выбираете папку и устанавливаете. Далее выполним установку интерпретатора  языка Python на свое устройство. У меня – это стационарный компьютер с ОС Windows 10. Если я нажму клавиши Win + Pause, то появится окно с подробной информацией о системе. В частности, здесь написано название ОС и ее разрядность x64. Конечно, у вас может быть любое другое устройство и ОС – это не существенно, в любом случае, нам нужно перейти на официальный сайт языка Python:  https://www.python.org\r\nЗатем, выбрать вкладку «Downloads» и здесь появится список различных ОС. Вам нужно найти свою ОС и перейти. Так как у меня Windows, то я выбираю этот пункт и появляется страница с выбором различных версий языка. Конечно же, следует взять последнюю стабильную для Python 3. Я скачаю 64-bit версию установщика:\r\nDownload Windows installer (64-bit) так как у меня ОС Windows 64-разрядная (обычно, именно такая и установлена на домашнем компьютере). И запущу его. Появится окно, в котором обязательно следует отметить галочкой так же и опцию «Add Python to PATH». Она позволит в дальнейшем запускать интерпретатор языка без указания полного пути к нему в том числе из Visual Studio Code.\r\nЗатем, выбираем режим установки «Customize installation». Здесь все опции должны быть отмечены галочками.\r\nНажимаем «Next» и в следующем окне я рекомендую путь, который прописан по умолчанию, изменить на другой. А именно, убрать все промежуточные подкаталоги и установить интерпретатор в корень выбранного диска на пример так:  «C:\\Python39»  где C - выбранный диск компьютера, а 39 скачиваемая версия языка 3.9. Это также рекомендуется делать, так как разных версий на одном устройстве может быть несколько и чтобы не путаться, они должны находиться в разных директориях.\r\nПосле этого, нажимаем на кнопку «Install» и программа устанавливается в указанный каталог. \r\nОсталось проверить работоспособность языка Python. Во-первых, мы можем открыть командную строку  в ОС Windows (Win+R) и в появившемся окне набрать «cmd» для открытия консольного окна.\r\nДалее, в  консольном окне набираем «python», терминал выдаст версию установленного python (Python 3.9.5) и ниже  символ >>>  после которого мигает курсор - это место называется  командной строкой интерпретатора Python, Здесь вводятся команды(коды) для исполнения на этом языке.  Нажмите на картинку в углу. Увидите результат в отдельном окне. \r\n\r\nСсылка на установку и настройку Python 3 и Visual Studio Code (VSCode) на ОС Windows 10:  \r\n\r\nhttps://rutube.ru/video/041d1f36eabc78ca7734a1295d386f87/', 'photos/2025/$m/05/image007.jpg', '2025-08-05 10:35:59.882069', '2026-03-19 09:12:01.577065', 1, 3);
INSERT INTO `adik_adik` (`id`, `title`, `slug`, `content`, `photo`, `time_create`, `time_update`, `is_published`, `cat_id`) VALUES
(13, 'Переменные и функции print() и input()', 'peremennaya_print', 'Вернемся к командной стpоке.\r\nПосле символа тройной стрелки >>> вводим команду print(\"Привет! Это моя первая строчка кода!\").  Нажимаем Enter и видим результат-свое сообщение. Несложно заметить, что это всего одна команда, в которой встроенной функции print () аргументом передается текст, который необходимо напечатать в консольном окне, никто не запрещает нам команда за командой выполнять программный код. Но это достаточно неудобно.  Обычно при написании более-менее серьезной программы ее оформляют в виде последовательности инструкций(команд) и записывают в отдельный файл. Затем файл размещается и выполняется в редакторе.\r\nДля работы с редактором сначала создадим папку (например uroki) на любом диске. В ней разместим  еще одну папку (например  bin). Отметим про себя, что любая папка это директория с файлами в которые мы будем помещать коды(сценарии). Наводим курсор на папку bin..  Правой мышью открываем папку с помощью редактора  VS Code.  В редакторе нажимаем на кнопку создать новый файл, называем его например file.py (.py -обязательное расширение для python файлов). Нажмем(откроем)  его. Нажимая сочетание клавиш Ctrl + Shift + P в Windows выбираем для связки установленный нами на компе интерпретатор( указываем путь к нему).\r\nДавайте напишем в нем(файле file.py) программу, которая считает от 1 до 3. Вот код, который нам для этого нужен:\r\nprint(\"1\")\r\nprint(\"2\")\r\nprint(\"3\")\r\nВ кладке \"Вид\" (при открытом файле) редактора переходим в терминал. В терминале будет указан путь к открытому файлу. Вписываем команду  python file.py  нажимаем Enter. Ниже получаем результат обработки кода. Программа сосчитала до трех? Довольно просто, правда?\r\nСнова правой мышью открываем папку bin с помощью редактора  VS Code.  В редакторе нажимаем на кнопку создать другой файл, называем его например 1.py (напоминаем.py -обязательное расширение для python файлов). Размещаем другой код:\r\n\r\nprint(\"Начинаем вычисления!\")\r\nа = 4\r\nprint(\"Значение переменной а=\", а)  # пробел после запятой\r\nЬ = 12\r\nprint(\"Значение переменной Ь=\", Ь)\r\nс = Ь / а\r\nprint(\"Результат деления Ь/а=\", с)\r\nprint(\"Вычисления закончены!\")\r\n\r\nНабираем в терминале команду-  python 1.py затем клавишу Enter смотрим результат:\r\n\r\nНачинаем вычисления!\r\nЗначение переменной а = 4\r\nЗначение переменной Ь = 12\r\nРезультат деления Ь/а = 3.0\r\nВычисления закончены!\r\n\r\nПрокомментируем соответствующие команды и результат их выполнения:\r\nИтак, командой print(\"Начинаем вычисления!\") в начале выполнения программы выводится текстовое сообщение. Таким образом, в начале выполнения программы появляется текст \"Начинаем вычисления\"!. Аналогично, благодаря  команде print(\"Вычисления закончены!\") , которая завершает программный код, признаком окончания выполнения программы является текстовое сообщение \"Вычисления закончены!\".\r\nМежду этими командами выполняются небольшие вычисления:\r\n• командой а = 4 переменной а присваивается числовое значение 4;\r\n• командой print(\"Значение переменной а=\", а) выводится текст, а затем значение переменной а;\r\n• командой b = 12 переменной b присваивается числовое значение 12;\r\n• командой print(\"Значение переменной Ь=\", Ь)  выводится текст и значение переменной Ь;\r\n• командой с = Ь / а переменной с в качестве значения присваивается\r\nрезультат деления значения переменной b на значение переменной а;\r\n• командой print(\"Результат деления Ь/а=\", с) выводится текст и числовое значение переменной с\r\n\r\nДля написания кода мы использовали  переменные a, b, c.  В них мы сохраняем данные - в кавычках если строки и без, если числа. В отношении переменных важны два момента:\r\n• у переменной есть имя (или название);\r\n• переменная ссылается на некоторое значение.\r\nВ принципе, значение, на которое ссылается переменная, мы можем прочитать и изменить при надобности.\r\nЗнак решетка - #  используется для написания комментариев. Все что пишется за этим знаком не видимо после вывода результата. Команда print() является встроенной функцией.\r\nФункции в языках программирования бывают встроенные (в язык программирования) и пользовательские- которые составляют (разрабатывают) сами программисты. В скобках функции размещаются аргументы. Аргументы бывают разных типов- строки, числа и т.д. Можно объединять аргументы-строки (такой прием называется \"конкатенация\"). Для этого между аргументами ставиться знак + (плюс). Например:\r\nprint(\"Значение переменной\" + \" если получиться будет результатом кода\"). Добавьте это в конец кода и снова распечатайте командой python 1.py. Получим результат:\r\n\"Значение переменной если получиться будет результатом кода\". Обратите внимание что перед \"если\" ставиться пробел. Это для того чтоб не слиплись две строки.\r\nТакже мы увидели, что функции print() можно передавать не только один, а несколько аргументов через запятую. В этом случае в область вывода последовательно, в одну строку, выводятся значения аргументов функции print().\r\n\r\nПример еще одной простой программы:\r\nВ программе, которую мы рассмотрим далее, реализуется следующий алгоритм:\r\n1. Выводится текстовое приветствие \"Как Вас зовут?\" с просьбой к пользователю указать имя- можно ввести любое имя и нажать Enter;\r\n2. После того, как пользователь вводит имя и нажимает Enter, оно считывается и записывается в  переменную;\r\n3. Программой выводится еще одно сообщение, а текст сообщения со\r\nдержит имя, которое на предыдущем шаге ввел пользователь.\r\n\r\nДля вывода сообщений в консольное окно используется функция print(),\r\nа для считывания введенного пользователем текста (имя пользователя) используем функцию input(). Также в программе есть комментарии. Полный код программы:\r\n\r\n# Выводится сообщение\r\nprint (\"Давайте познакомимся, если не жалко!\")\r\n# Считываем введенное пользователем значение \r\n# Результат присваивается в переменную name\r\nname = input(\"Как Вас зовут?\")\r\n# Выводиться новое сообщение:\r\nprint(\"Добрый день,\",name+\"!\")\r\n\r\nРезультат кода с именем Nik:\r\nДавайте познакомимся, если не жалко!\r\nКак Вас зовут?Nik\r\nДобрый день, Nik!\r\n\r\n\r\n\r\n\r\n\r\n', 'photos/2026/$m/17/JaInfo.jpg', '2026-03-17 04:37:13.258848', '2026-05-07 10:08:06.033379', 1, 3),
(14, 'Основные операторы', 'operatori', 'Мы уже имели дело с переменными. В первую очередь, что касается названия переменных: в принципе, это может быть практически любое имя (комбинация букв,цифр и символов подчеркивания), которое не совпадает ни с одним из ключевых(встроенных) слов Python. Попытка использовать переменную c соответствующим именем приведет к ошибке.\r\n\r\nТеперь познакомимся с операторами в Python.\r\nОбычно выделяют  четыре группы операторов:\r\n\r\n• арифметические;\r\n• побитовые;\r\n• операторы сравнения;\r\n• логические операторы.\r\n\r\nАрифметические операторы предназначены в первую очередь для выполнения арифметических вычислений. В таблице ниже перечислены и кратко описаны основные арифметические операторы языка Python.\r\nСразу следует отметить, что действие арифметических операторов достаточно точно соответствует \"математической природе\" этих операторов. При этом мы предполагаем, что речь идет о числовых расчетах.\r\n\r\nАрифметические операторы:\r\n\r\nОператор ->  Описание\r\n   +         Оператор сложения. Вычисляется сумма двух чисел\r\n   -          Оператор вычитания. Вычисляется разность двух чисел\r\n   ★        Оператор умножения. Вычисляется произведение двух чисел\r\n   /          Оператор деления. Вычисляется отношение двух чисел\r\n  //          Оператор целочисленного деления. Вычисляется целая\r\n               часть от деления одного числа на другое\r\n   %         Оператор вычисления остатка от целочисленного деления.\r\n               Вычисляется остаток от деления одного числа на другое\r\n  **          Оператор возведения в степень. Результатом является число,               получающееся возведением первого операнда в степень, определяемую вторым операндом.\r\nПример программного кода для выполнения несложных арифметических\r\nвычислений:\r\ne = (5 + 2) * * 2 - 3 * 2      # Результат 43\r\nk = 6 - 5/2                    # Результат 3.5\r\nm = 10//4 + 10 % 3             # Результат 3\r\n# Результаты вычислений выводим на экран\r\nprint(\"Результаты вычислений:\")\r\nprint(e,k,m)\r\nДобавим тот код в конец кода в файле 1.py. Файл->Сохранить. И в терминале командой python 1.py выводим результат в строку:\r\nРезультаты вычислений:\r\n43 3.5 3\r\nПобитовые (или двоичные) операторы очень близки к арифметическим в том отношении, что тоже предназначены для работы с числовыми значениями. Только в случае побитовых операторов вычисления выполняются\r\nна уровне двоичного кода числа. Для эффективного использования побитовых операторов необходимо неплохо разбираться в двоичном представлении чисел. Более\r\nподробно мы остановимся на них в другой раз. Пример некоторых из них:\r\n\r\nПобитовые операторы:\r\n\r\nОператор ->  Описание\r\n\r\n   |      ->   Побитовое ИЛИ. Сравниваются побитовые представления операндов\r\n   ^     ->   Побитовое исключающее ИЛИ\r\n   &     ->   Побитовое И. Для сравнения при вычислении результатов\r\n   <<    ->   Сдвиг влево. \r\n   >>    ->   Сдвиг вправо.\r\n\r\nЛогические операторы:\r\n\r\nС логическими значениями мы столкнемся при проверке условий в условной\r\nинструкции (операторе). Значений у логического типа всего два: True (истина) и False (ложь). Для работы со значениями логического типа предназначены специальные операторы, которые принято называть логическими. \r\n\r\nОператор -> Описание\r\n\r\nor   ->   Бинарный оператор (у оператора два операнда). Логическое ИЛИ. В \r\n              общем случае результатом выражения х or у является True , \r\n              если значение хотя бы одного из операндов х или у равно True.\r\n              Если значения обеих операндов х и у равны False , \r\n              результатом выражения х or у будет False .\r\n         \r\nand   ->   Бинарный оператор (у оператора два операнда).Логическое И. В\r\n               общем случае результатом выражения х and у является значение \r\n               True , если значения обеих операндов х и у равны True . \r\n               Если значение хотя бы одного из операндов х или у равно \r\n               False , результатом выражения х and у будет False .\r\n\r\nnot   ->   Логическое отрицание. Унарный оператор (у оператора\r\n               один операнд). Результатом выражения not х будет значение True, \r\n               если у операнда х значение False . Результатом выражения not х\r\n               будет значение False , если у операнда х значение True\r\n\r\nКоме того логические значения True и False можно использовать, соответственно, как числа 1 и 0 ( True это 1; False  0 )\r\n\r\nОператоры сравнения позволяют сравнивать на предмет равенства/неравенства различные значения. Обычно (хотя и не всегда) речь идет о числовых значениях. Результатом операций сравнения являются логические значения: True , если соответствующее соотношение верно (если отношение имеет место), и False , если неверно (отношение не имеет место). Здесь и далее для упрощения темы мы будем говорить об операциях сравнения только в основном для числовых значений.\r\nПрограммный код, приведенный ниже дает представление о том,как с применением логических операторов вычисляются логические выражения:\r\na = True\r\nb = not a\r\nprint(а, b)\r\nс = а and b\r\nd = a or b\r\nprint(с, d)\r\nДобавим его также в конец кода в файле 1.py. Файл->Сохранить. И в терминале командой python 1.py выводим результат в строку, не забывая вставить имя:\r\n\r\nНачинаем вычисления! \r\nЗначение переменной а= 4 \r\nЗначение переменной Ь= 12\r\nРезультат деления Ь/а= 3.0\r\nВычисления закончены!\r\nЗначение переменной если получиться будет результатом кода\r\nДавайте познакомимся, если не жалко!\r\nКак Вас зовут? Nik \r\nДобрый день, Nik! \r\nРезультаты вычислений:\r\n43 3.5 3\r\nTrue False\r\nFalse True\r\n\r\nИтак- Операторы сравнения:\r\n\r\nОператор -> Описание:\r\n\r\n <             Строго меньше. Результатом является True , если значение операнда слева от \r\n                оператора меньше значения операнда справа от оператора. \r\n                Иначе возвращается значение False \r\n\r\n>             Строго больше. Результатом является True , если значение операнда слева от \r\n               оператора больше значения операнда справа от оператора. \r\n               Иначе возвращается значение False\r\n\r\n<=           Меньше или равно. Результатом является True , если значение операнда слева от \r\n                оператора не больше значения операнда справа от оператора.\r\n                Иначе возвращается значение False\r\n\r\n>=           Больше или равно. Результатом является True , если значение операнда слева от \r\n                оператора не меньше значения операнда справа от оператора. \r\n                Иначе возвращается значение False\r\n\r\n==           Равно. Результатом является True , если значение операнда слева \r\n                от оператора равно значению операнда справа от оператора. \r\n                Иначе возвращается значение False\r\n\r\nI =           Не равно. Результатом является True , если значение\r\n               операнда слева от оператора не равно значению операнда справа от оператора.\r\n                Иначе возвращается значение  False\r\n\r\n Is           Оператор проверки идентичности объектов. В качестверезультата возвращается \r\n               значение True, если оба операнда ссылаются на один и тот же объект.\r\n               В противном случае (то есть если операнды ссылаются на разные объекты)\r\n               возвращается значение False\r\n\r\nis not     Оператор проверки неидентичности объектов. В качестверезультата возвращается \r\n                значение True, если операнды ссылаются на разные объекты. В противном случае\r\n                (то есть если операнды ссылаются на один и тот же объект)\r\n                возвращается значение False\r\n\r\nНебольшие пример использования операторов сравнения:\r\n\r\nm = 100\r\ns = 200\r\nprint(m < s, m >= s, m == 100, s != 199)\r\n\r\nОткроем (если закрыли) папку bin в редакторе. Добавим также в конец кода в файле 1.py. Файл->Сохранить. И в терминале командой python 1.py выводим результат в строку, не забывая вставить имя:\r\nПолучим True False True True\r\n\r\nВ заключение  сделаем важное замечания первое касается так называемой сокращенной формы оператора присваивания:\r\n\r\nНапример, вместо команды х=х+у можно использовать сокращенно команду х+=у.\r\nИли  вместо x=x-y можно использовать сокращенно команду х-=у и т.д\r\n\r\nВторое замечание касается приоритета различных операторов. В сложных выражениях одновременно могут присутствовать самые разные операторы.\r\nТакие выражения вычисляются в соответствии с приоритетом операторов. Сначала вычисляются выражения и подвыражения с операторами, которые имеют более высокий приоритет, а уже затем вычисляются выражения и подвыражения с более низким приоритетом. Если несколько операторов \r\nимеют одинаковые приоритеты, выражение вычисляется слева направо. Вкратце приоритет операторов в Python следующий (в порядке уменьшения приоритета):\r\n\r\n• побитовая инверсия, возведение в степень, знак числа (унарный минус или унарный плюс);\r\n• умножение, деление, целочисленное деление, остаток от деления;\r\n• сложение, вычитание;\r\n• побитовые сдвиги;\r\n• побитовое И;\r\n• побитовое И СПЛЮ ЧАЮЩЕЕ ИЛИ;\r\n• побитовое ИЛИ;\r\n• оператор присваивания (включая и сокращенные формы)\r\n\r\nДля изменения порядка вычисления выражения можно использовать круглые скобки. Сначала вычисления производятся в скобках. Более того, наличие в правильном месте круглых скобок (даже если острой необходимости в них нет), не только делает код более \"надежным\", но и значительно повышает его читабельность.\r\n\r\nДля выполнения математических вычислений предназначен целый ряд встроенных функций. Некоторые полезные в работе математические функции представлены ниже:\r\n\r\nint () -->   Функция для преобразования объекта (например, текста) в целое число.\r\n\r\nmax () --> Функция для вычисления максимального значения из набора чисел.\r\n\r\nmin () --> Функция для вычисления минимального значения из набора чисел.\r\n\r\npow () --> Функция для возведения в степень числа.\r\n\r\nБольшое количество математических функций становится доступным после подключения модуля math . После этого, например, можем в программном коде использовать тригонометрические функции, такие, как s i n () (синус), c o s () (косинус), t a n () (тангенс) и многие\r\nдругие.  Для этого в самой верхней строке программного кода достаточно добавить инструкцию import math. При вызове функций из этого модуля придется перед именем функции указывать название модуля (разделитель имени модуля и имени функции - точка): на\r\nпример, math.sin(), math.cos() и т.д. Добавим в наш код дополнения. Теперь код будет иметь вид:\r\n\r\nimport math\r\n\r\nprint(\"Начинаем вычисления!\")\r\nа = 4\r\nprint(\"Значение переменной а=\", а)  # пробел после запятой\r\nЬ = 12\r\nprint(\"Значение переменной Ь=\", Ь)\r\nс = Ь / а\r\nprint(\"Результат деления Ь/а=\", с)\r\nprint(\"Вычисления закончены!\")\r\n\r\nprint(\"Значение переменной\" + \" если получиться будет результатом кода\")\r\n# Выводится сообщение\r\nprint(\"Давайте познакомимся, если не жалко!\")\r\n# Считываем введенное пользователем значение\r\n# Результат присваивается в переменную name\r\nname = input(\"Как Вас зовут? \")\r\n# Выводиться новое сообщение:\r\nprint(\"Добрый день,\", name + \"!\")\r\n\r\ne = (5 + 2) ** 2 - 3 * 2  # Результат 43\r\nk = 6 - 5 / 2  # Результат 3.5\r\nm = 10 // 4 + 10 % 3  # Результат 3\r\n# Результаты вычислений выводим на экран\r\nprint(\"Результаты вычислений:\")\r\nprint(e, k, m)\r\n\r\nd = True\r\nv = not d\r\nprint(d, v)\r\nx = d and v\r\nz = d or v\r\nprint(x, z)\r\n\r\nm = 100\r\ns = 200\r\nprint(m < s, m >= s, m == 100, s != 199)\r\n\r\n\r\n# Тригонометрические функции:\r\n\r\n# 1. Задаем угол в градусах\r\nangle_deg = 90\r\n# Python предоставляет полный набор тригонометрических функций. Важнейшим аспектом при их\r\n# использовании является то, что все они работают с углами, выраженными в радианах, а не в градусах.\r\n# 2. Конвертируем в радианы  через модуль radians\r\nangle_rad = math.radians(angle_deg)\r\n# 3. Вычисляем синус присваивая переменной sin_value\r\nsin_value = math.sin(angle_rad)\r\n# Выводим результат:\r\nprint(\r\n    f\"Синус {angle_deg} градусов равен: {sin_value}\"\r\n)  # конструкция f для вставки в строку  переменных в {};\r\n\r\nЗапускаем в терминале командой python 1.py -   получаем результат:\r\n \r\nНачинаем вычисления! \r\nЗначение переменной а= 4 \r\nЗначение переменной Ь= 12\r\nРезультат деления Ь/а= 3.0\r\nВычисления закончены!\r\nЗначение переменной если получиться будет результатом кода\r\nДавайте познакомимся, если не жалко!\r\nКак Вас зовут? Nik \r\nДобрый день, Nik! \r\nРезультаты вычислений:\r\n43 3.5 3\r\nTrue False\r\nFalse True\r\nTrue False True True\r\nСинус 90 градусов равен: 1.0', 'photos/2026/$m/17/operatori.jpg', '2026-06-04 11:16:07.000000', '2026-06-22 18:56:23.300880', 1, 3),
(22, 'Условные операторы. Операторы цикла', 'uslovniei', 'Для изучения темы откроем редактор - папку bin – создадим в ней файл 3.py\r\n\r\n1. Что такое условные операторы?\r\n\r\n\r\nМы проверяем условия, и даем себе инструкции каждый день:\r\nЕсли сегодня солнечно, то надену очки.\r\nЕсли в кафе есть WiFi, то спрошу у официанта пароль. Как Вы заметили, оба примера сверху содержат условие, которое начинается с если (если сегодня холодно, если в кафе есть WiFi), и инструкции (надену очки, спрошу пароль). Компьютерные программы тоже проверяют условия, чтобы следовать конкретным инструкциям. Если условие срабатывает, программа возвращает True (помните True и False?), и выполняет одну инструкцию. Если условие не срабатывает, программа возвращает False, и выполняет другую инструкцию. Например, когда Вы хотите зайти на сайт, и вводите верный пароль, программа возвращает True, и выполняет инструкцию, которая говорит ей впустить вас. Если Ваш пароль неверный, программа возвращает False, и следует другой инструкции, которая говорит ей не впускать вас. Это и есть упрощенно представление того, как работают условные операторы в Python, и в других языках. Программа проверяет условие и следует заявленной инструкции, в \r\nзависимости от того, сработало условие, или нет. \r\n\r\n2. Условный оператор If :\r\n\r\nIf – это условный оператор. Он переводится как “Если”. Мы используем его, когда говорим программе, что нужно сделать, если условие сработало. А теперь давайте посмотрим, как надо работать с этим условным оператором. Вот Вам пример для иллюстрации. Это небольшая программа, которая проверяет Ваш пароль и, если пароль верный, то программа приветствует Вас на сайте.\r\n\r\nпароль = \"секрет\"\r\nif пароль == \"секрет\":\r\n….print(\"Добро пожаловать на сайт!\")    # четыре точки условное отображение отступов(пробелов)\r\n\r\nВпишите этот код в файл 3.py и запустите его. Давайте разберем код подробнее.На первой строчке мы указали условие: пароль = “секрет”. На второй строчке мы прописали оператор if, а затем условие, которое нужно проверить. То есть проверить, что пароль действительно равен значению “секрет”. И поставили двоеточие после условия;\r\nИ, наконец, на третьей строчке, мы прописали инструкцию вывести сообщение на экран на случай, если условие окажется верным, и программа вернет True. При этом сама инструкция выводит сообщение “Добро пожаловать на сайт!” на экран. Кстати, Вы заметили двоеточие в конце второй строчки? Оно нужно для того, чтобы программа поняла, где заканчивается условие, которое мы задали, и где начинается инструкция. Двоеточие всегда ставится после условия, и перед инструкцией. И, наконец, Вы наверное обратили внимание на то, что в этом коде, инструкция \r\nначинается после отступа (это стандартный способ выделения блоков команд в языке Python). В принципе, количество отступов может быть произвольным - главное, чтобы для каждой команды блока делалось одно и то же количество отступов. Но общепринятым является правило делать 4 отступа (4 пробела). Для наглядности мы в коде будем отступы отображать точками. Но в редакторе отступы отображаются через пробел, при этом практически во всех редакторах отступы отображаются автоматически. Отступ перед инструкцией нужен для того, чтобы программа поняла, что эта инструкция относится именно к этому условию. Попробуйте убрать отступ, и запустите программу снова. Вы увидите, что программа вернула ошибку.\r\n\r\n\r\n2.1. if и операторы сравнения\r\n\r\nКак Вы уже поняли из нашего примера с паролем, условный оператор if прекрасно работает с операторами сравнения. Вот Вам еще один пример:\r\n\r\nдень = \"Пятница\"\r\nif день == \"Пятница\":\r\n….print(\"Ура! Пятница!\")\r\n\r\nВпишите этот код в файл 3.py и запустите его на исполнение. А теперь поиграйте с этим кодом. Замените == на !=(не равно) и перезапустите его. Что теперь выдает программа? Правильно, ничего теперь не выдает. Потому что у программы есть инструкция на случай, если условие выполнено. А на случай, если условие не выполнено, инструкции нет. Вот программа и замолчала. Не переживайте. Чуть позже,  Вы научитесь решать эту проблему. А пока продолжим.\r\n\r\n\r\n2.2. Условный оператор if и числа:\r\n\r\nС помощью условного оператора if можно сравнивать не только строки, но и числа. Смотрите, как это можно сделать:\r\n\r\nочки = 100\r\nif очки == 100:\r\n….print(\"Вы выиграли!\")\r\n\r\nЗапишите этот код в наш файл 3.py, и запустите его. Давайте теперь разберем, что здесь к чему. Сначала мы создали переменную очки, и присвоили ей значение в виде целого числа 100. Затем мы написали условное заявление(условие), в котором, если значение очков равно сотне, программа должна вернуть сообщение “Вы выиграли!”. С if мы можем использовать не только оператор равно, но и другие операторы сравнения. Например, такие операторы, как больше или меньше. Давайте дополним нашу программу условием, в котором есть оператор – меньше.Вот, как мы можем это сделать:\r\n\r\nочки = 50\r\nif очки < 100:\r\n….print(\"Эй! Вам нужно больше очков!\")\r\n\r\nВпишите этот код в файл 3.py, и запустите его. Что теперь возвращает программа? А теперь, давайте сделаем то же самое с условием, в котором есть оператор больше:\r\n\r\nочки = 101\r\nif очки > 100:\r\n….print(\"Ух ты! У Вас новый рекорд!\")\r\n\r\n3. Условный оператор else (“Иначе”):\r\n\r\nМы узнали, что такое оператор if, и что он делает. Теперь давайте изучим оператор “else”. Оператор else сообщает программе, что делать, если первое условие не сработало. Вот, как это выглядит на примере:\r\n\r\nочки = 99\r\nif очки == 100:\r\n….print(\"Вы выиграли!\")\r\nelse:\r\n….print(\"Вам нужно больше очков!\")\r\n\r\nЗапишите этот код в файл, и запустите его. Как Вы уже поняли, теперь у нас есть два условия и две инструкции, для каждого условия. Первое условие создано при помощи оператора if, а второе – при помощи оператора else. Приведу для Вас еще один пример. Но, на этот раз я специально кое-что упустил в нем:\r\n\r\nжизни = 1\r\nif жизни == 0:\r\n….print(\"Игра окончена\")\r\n:\r\n….print(\"Сыграть еще раз?\"\r\n\r\nВаша задача вписать этот код в файл 3.py, выяснить, чего не хватает, исправить это, и запустить наш код. Ну как, получается? :)\r\n\r\n4. Условный оператор elif:\r\n\r\nВы уже знаете об условных операторах if, else, и для чего они нужны. Пришло время познакомиться с условным оператором elif. Elif происходит от комбинации операторов else и if. Перевести elif можно как  “Иначе если”. Для чего нам нужен оператор elif? Elif помогает нам добавлять в программу дополнительные условия и соответствующие инструкции. Вот, как это выглядит на примере:\r\n\r\nвремя = 12\r\nif время <12:\r\n….print(\"Доброе утро!\")\r\nelif врея < 17:\r\n….print(\"Добрый день!\")\r\n\r\nДобавьте этот код  и запустите его. Давайте рассмотрим его поподробнее. Здесь мы создали два конкретных условия и две конкретные инструкции. Одно условие и инструкция стоят после if.  Второе условие и инструкция стоят после elif. Если  есть оператор else, зачем еще и elif?\r\nХороший вопрос! Дело в том, что в отличие от else, условныйоператор elif можно использовать столько раз подряд, сколько конкретных условий и инструкций мы хотим прописать. Вот, как выглядит пример с двумя elif подряд:\r\n\r\nвремя = 12\r\nif время <12:\r\n….print(\"Доброе утро!\")\r\nelif время < 17:\r\n….print(\"Добрый день!\")\r\nelif время < 21:\r\n….print(\"Добрый вечер!\")\r\n\r\nВпишите этот код в файл 3.py в редакторе, и запустите его(команда python 3.py).\r\n\r\nЕсли с этим все понятно, вот Вам еще немного самостоятельной работы:\r\n\r\nвремя = 12\r\nif время <12:\r\n….print(\"Доброе утро!\")\r\n….время < 17:\r\n….print(\"Добрый день!\")\r\n….время < 21:\r\n….print(\"Добрый вечер!\")\r\n\r\nВ этом коде кое-чего не хватает. Дополните код, и запустите его. Справились? Отлично! \r\nА теперь поговорим о порядке применения if, elif и else.\r\n\r\n5. Порядок if, elif и else:\r\n\r\nКогда мы используем условные заявления, оператор if всегда идет первым. Так мы сообщаем программе конкретное условие и инструкцию, которую программа выполнит, если условие сработает. Затем идет elif. Так мы сообщаем программе другие конкретные условия и конкретные \r\nинструкции по каждому из условий. И, наконец, условный оператор else. Он идет в самом конце. Так мы сообщаем программе инструкцию, которой она должна следовать, если ни одно из условий выше не сработало. Вот, как выглядит такой порядок на примере:\r\n\r\nвремя = 22\r\nif время <12:\r\n….print(\"Доброе утро!\")\r\nelif время < 17:\r\n….print(\"Добрый день!\")\r\nelif время < 21:\r\n….print(\"Добрый вечер!\")\r\nelse:\r\n….print(\"Спокойной ночи!\")\r\n\r\nВпишите этот код и запустите его. Итак, запоминаем: Сначала if, затем elif, и только потом else.\r\n\r\nБолее сложный пример использования условного оператора:\r\n\r\n# Пользователь вводит значение, которое присваивается переменной res\r\nres = eval(input (\"Введите что-нибудь: \")) # eval- функция в качестве подстраховки\r\n# Используем условный оператор для проверки типа введенного\r\n# пользователем значения\r\nif type(res) == int:\r\n# Если ввели целое число (4 пробела-отступа не забываем)\r\n....print(\"Вы ввели целое число!\")\r\nelse:\r\n# Если что-то другое\r\n....print (\"Это точно не целое число!\")\r\n# После выполнения условного оператора \r\nprint(\"Работа завершена\")\r\n\r\nПри запуске программы на выполнение сначала появляется запрос для ввода пользователем некоторого значения. Введенное пользователем значение считывается и запоминается. Затем проверяется тип введенного пользователем значения: если точнее, проверяется, не целочисленное ли значениеввел пользователь? Д ля этого используется условный оператор. Если польпователь ввел целое число, \r\nвыводится соответствующее сообщение. Если то, что ввел пользователь, не является целым числом, тоже появляется со-общение, но уже другое. Наконец, после завершения выполнения условного оператора появляется сообщение об окончании работы программы.\r\nЗайдем снова в редактор VS Code . Содадим в папке bin  новый файл 2.py. Для этого наводим на папку курсор- справа в иконке создать новый файл-вводим имя файла 2.py- Enter. В открывшимся файле вставляем выше набра-\r\nный код. В терминале вводим команду python 2.py нажимаем Enter и видим результат:\r\n\r\nВведите что-нибудь: 5 # ввели 5\r\nВы ввели целое число!\r\nРабота завершена\r\n\r\nПовторяем исполнение (команда python 2.py в терминале), но вводим 2.5\r\n\r\nВведите что-нибудь: 2.5\r\nЭто точно не целое число!\r\nРабота завершена\r\n\r\nПонятно, что результат выполнения программного кода зависит от ввода пользователя. Мы уже знакомы с функцией input(). Она возвращает текстовое представление тех данных, которые вводит пользователь. То есть даже если пользователь вводит число,оно все равно будет представлено в текстовом формате (это называется текстовое представление числа). Неопределенность ситуации в том, что у нас нет гарантии в том, что пользователь ввел число. В принципе этом может быть какой-угодно текст. Поэтому мы подстраховываемся:\r\nрезультат функции input()  передаем аргументом функции eval(). Функция eval() пытается \"вычислить\" выражение, \"спрятанное\" в тексте. Если там спрятано целое число, результатом будет это число.\r\nФункцией же type() вычисляем тип введенного пользователем значения. В частности, в условном операторе проверяется выражение значения.\r\ntype(res) == int , которое имеет значение True(истинна) если тип значения, на которое ссылается переменная res , равен int (то есть если это целое число) .Если пользователь действительно ввел целое число, выполняется команда print(\"Вы ввели целое число!) . В противном случае (если не выполнено условие type(res) = = int ) выполняется команда print (\"Это точно не ыцелое число\" ). На этом блок условного оператора заканчивается. Команда print (\"Работа завершена !\") выполняется уже после завершения условного оператора.\r\n\r\nДопускается использование упрощенной формы оператора без else -блока:\r\n\r\nif условие: \r\n....к о м а н д ы \r\n\r\nВ некоторых случаях разумнее использовать несколько вложенных условных операторов. На этот случай в Python имеется специальная версия условного оператора-  еlif( промежуточное между if и else):\r\n\r\nif условие_1:\r\n....команды_1\r\nelif условие_2:\r\n....команды_2\r\nelif условие_3:\r\n....команды_3\r\n….\r\nelse:\r\n....команды для завершения блока\r\n\r\nВ данном случае начало традиционное: после ключевого слова if указывается условие для проверки (обозначено условие_1). Если условие истинно, выполняются команды if -блока (обозначены как команды_1). Если выражение  условие_1 ложно, проверяется условие, указанное после ключевого слова elif (в шаблоне условие обозначено как условие_2 , после условия ставится двоеточие :). Если это, второе, условие истинно, выполняются команды для данного elif -блока (команды этого блока обозначены как команды_2), и на этом работа условного оператора завершается. Если же и выражение  условие_2 ложно, проверяется условие в следующем elif -блоке, и в случае его истинности - команды этого блока.\r\nЕсли при переборе elif -блоков ни одного истинного условия не обнаружено, выполняются команды else -блока, который размещается в шаблоне самым последним.\r\n\r\nЦИКЛЫ:\r\n\r\nЦиклы в Python, как и в других языках программирования помогают избежать \r\nповторения одних и тех же инструкций в коде. Они делают  код более изящным и \r\nэффективным. Давайте узнаем как они выглядят и что эти циклы конкретно делают\r\n\r\n1. Что такое Циклы?\r\n\r\nОчень часто, программы повторяют одну и туже задачу, раз за разом. Например складывают числа пока не получиться нужная сумма этих чисел.\r\nНапример, вот как выглядит программа которая повторяет счет до трех и выводит это на экран:\r\n\r\nчисло = 1\r\nprint(число)\r\nчисло = число + 1\r\nprint(число)\r\nчисло = число + 1\r\nprint(число)\r\n\r\nСоздайте в редакторе файл 4.py и впишите в него код , запустите и проверьте. Как видите, мы создали переменную с именем число, присвоили ей значение единица, \r\nа затем отобразили ее на экране с помощью функции print(). Затем, чтобы увеличить число от одного до двух, мы снова взяли нашу переменную, присвоили ей \r\nтекущее значение, добавили к нему 1, и снова отобразили ее на экране с помощью функции print. Затем мы повторили предыдущий шаг, чтобы получилось три. Вроде работы немного. Но представьте, если бы нам пришлось считать до миллиона? Сколько строчек кода нам пришлось бы писать? К счастью, для того, чтобы не повторять одни и те же инструкции в коде, программисты используют циклы. Давайте возьмем реальный пример того, как они применяются.\r\nДопустим, Вы играете в видеоигру со своим другом. Вы видите своего соперника, и начинаете стрелять из  автоматического оружия. Пока Вы удерживаете левую кнопку мыши, Ваше оружие продолжает стрелять. Это происходит потому, что в программе используется цикл, который говорит следующее: «Стрелять, пока зажата кнопка». Не будь этого цикла, Вам бы пришлось постоянно кликать мышью, чтобы продолжать \r\nстрельбу. А еще циклы отвечают за движения в играх. Пока зажата клавиша “вперед”,  игрок движется вперед. Вам не приходится постоянно нажимать на клавишу. Вы просто держите ее зажатой, и цикл “двигаться вперед” непрерывно действует. Итак, как Вы поняли, циклы – штука довольно полезная. Давайте теперь узнаем, как \r\nэти циклы применяются в Python.\r\n\r\n2. Цикл while:\r\n\r\nЦикл while переводится как “пока” и он работает пока определенное условие действует. (То есть возвращает True). Вот, как выглядит этот цикл вместе с булевым значением true:\r\nwhile true.\r\n\r\nА теперь давайте добавим в этот цикл инструкцию:\r\n\r\nчисло = 1\r\nwhile True:\r\n….print(число)\r\n….число = число + 1\r\n\r\nЕсли записать этот код в файл 4.py и запустить его. То получим бесконечный цикл. Программа не останавливается? :) если  ее не остановить принужденно. Цикл while \r\nбудет работать, пока определенное условие действует. (То есть возвращает True).\r\n\r\n3. Как остановить цикл while:\r\n\r\nИтак, пока цикл while возвращает True, он не остановится. Но как нам его остановить? Давайте изменим наш предыдущий код так, чтобы он проиграл цикл один раз и \r\nостановил его. Вот как это выглядит:\r\n\r\nсообщение = True\r\nwhile сообщение == True:\r\n….print(\"Один раз и хватит!\")\r\n….сообщение = False \r\n\r\nВпишите эту программу в файл 4.py, и запустите его. Давайте разберем ее подробнее. Сначала мы создали переменную “сообщение” и присвоили ей значение True.\r\nЗатем мы создали условие, используя цикл while. В этом условии сказано, что пока значение переменной “сообщение” равно True, программа должна выполнять \r\nинструкцию по выводу строки “Один раз и хватит!” на экран. Затем мы создали значение False, и сохранили его в переменной “сообщение”. Как Вы уже знаете,\r\nPython исполняет код построчно. Сверху вниз. А значит, сначала программа видит переменную “сообщение” и ее значение True. Затем программа видит условие, которое запускает цикл по выводу строки “Один раз и хватит!” на экран, пока “сообщение” равно True. И наконец, спустившись на последнюю строчку, программа видит что переменная “сообщение” больше не равна True и следовательно останавливает цикл. Цикл while остановлен.\r\n\r\n4. Цикл while и операторы сравнения:\r\nЦикл While и операторы сравнения можно использовать вместе. Давайте посмотрим, как это выглядит на примере. Эта программа(код) считает от одного до десяти. \r\nБлагодаря циклу while и оператору сравнения, мы уложились всего в четыре строчки кода, чтобы написать такую программу.\r\n\r\nчисло = 1\r\nwhile число <=10:\r\n….print(число)\r\n….число = число + 1\r\n\r\nЗапишите этот код в файл 4.py и запустите его также в редакторе VS Code\r\n\r\n5. Цикл while и обратный отсчет:\r\n\r\nПри помощи цикла while можно вести и обратный отсчет. Обратный отсчет в программах – очень полезная штука.Например, обратный отсчет используют в видеоиграх, чтобы считать сколько осталось времени, патронов, здоровья, защиты, противников. Ну Вы поняли. А раз так, давайте напишем программу, которая ведет обратный отсчет от десяти до одного. На этот раз, для того, чтобы объяснить Вам значение каждой строчки в коде, я написал комментарии над каждой строчкой. Напоминаю- комментарии в Python пишутся после знака #. Благодаря комментариям программисты запоминают что, где и для чего они писали. Не волнуйтесь, комментарии не мешают работе программы. Python игнорирует любые символы, которые пишутся после знака #. Поэтому не забывайте его ставить, когда будете писать собственные комментарии. Итак, вернемся к программе которая ведет обратный отсчет от десяти до одного:.\r\n\r\nСначала приведу код без комментариев. Вот он:\r\nчисло = 10\r\nwhile число >= 1:\r\n….print(число)\r\n….число = число – 1\r\n\r\nТеперь за комментированный код:\r\n\r\n# сохраняем 10 в переменной \"число\"\r\nчисло = 10\r\n# создаем цикл, который работает при условии, что больше или равно 1\r\nwhile число >= 1:\r\n# выводим значение числа на экран, пока работает цикл\r\n….print(число)\r\n# отнимаем от числа по единице пока работает цикл\r\n….число = число – 1\r\n\r\nЗапишите этот код в файл 4.py и запустите его также в редакторе VS Code командой python 4.py. Посмотрите, что он выводит.\r\n\r\nРассмотрим   пример по сложнее, в котором вычисляется сумма натуральных чисел. Соответствующий программный код:\r\n\r\nprint (\"Сумма натуральный чисел\")\r\nn = 100 # Количество слагаемых\r\n# Формируем текст для отображения результата и присваиваем переменной text\r\ntext = \"1 + 2 + . . . + \" + str(n) +\" = \"\r\n#  Итерационная переменная для оператора цикла\r\ni = 1\r\n# Переменная для записи суммы\r\ns = 0\r\n#  Оператор цикла для вычисления суммы (пока i меньше или равно n)\r\nwhile i < = n :\r\n#  Добавляем слагаемое к сумме\r\n....s = s + i\r\n# Изменяем итерационную переменную\r\n....i = i + 1\r\n# Отображаем результат\r\nprint(text , s)\r\n\r\nКопируем и вставляем код в редактор(файл 2.py) и через команду python 2.py выводим результат в терминале. Не забываем про отступы. На выходе по этому коду получим:\r\nСумма натуральный чисел\r\n 1+ 2 + . . . + 100 =  5050\r\n\r\nКак тот код работает? Основу кода составляет оператор цикла, при выполнении которого осуществляются основные вычисления. Перед выполнением оператора цикла командой print(\"Сумма натуральных чисел\") выводится сообщение о том, что мы собираемся вычислять сумму натуральных чисел. Далее объявляется несколько переменных. Переменная n (со значением 100 ) определяет количество слагаемых в сумме. В данном случае мы будем вычислять сумму 100 натуральных чисел: то есть сумму от 1 до 100 . Также нам понадобится текстовое значение, \r\nкоторое мы выведем в консоли терминала при отображении результата вычислений. С этой целью переменной text присваивается значение \"l + 2 + . . . + \" + s t r ( n ) + \" =\".\r\nЭто текстовое значение. Получается оно объединением (конкатенацией) трех текстовых фрагментов: \"l + 2 + . . . + \" , str(n) и \" =\". Для объединения использован оператор сложения. Для перевода числового значения в текстовое мы использовали функцию \r\nstr(), которая для подобных целей и предназначена. Также мы определяем итерационную (используется в операторе цикла для \"индексации\" \r\nциклов) переменную i с начальным значением 1. Это первое слагаемое, которое мы добавим к сумме. Результат (значение суммы) будем записывать в переменную s, у которой начальное значение нулевое. После этого выполняется оператор цикла.  Начинается он с инструкции while , после которой указано условие i< = n . Это означает,  что оператор будет выполняться до тех пор, пока значение переменной i (итерационная переменная, она же определяет слагаемое, прибавляемое к сумме) не превышает значение переменной n (последнее слагаемое в сумме). В теле оператора цикла выполняется две команды. Командой s = s + i добавляем очередное слагаемое к сумме, а затем \r\nкомандой i = i + 1 на единицу увеличиваем значение итерационной переменной. После выполнения оператора цикла командой print (text , s) отображаем в консольном окне результат вычислений. Вместо команды s= s+ i можно было использовать эквивалентную ей команду\r\ns + = i, а вместо команды i = i + 1 - соответственно, команду i+ = 1.', 'photos/2026/$m/23/uroki.jpg', '2026-06-23 11:52:37.958589', '2026-06-26 19:20:35.536875', 1, 3);
INSERT INTO `adik_adik` (`id`, `title`, `slug`, `content`, `photo`, `time_create`, `time_update`, `is_published`, `cat_id`) VALUES
(23, 'Списки. кортежи и словари', 'spiski', 'СПИСКИ:\r\n\r\nСписки позволяют нам хранить данные с разным форматом, и обращаться к этим данным, когда нам это необходимо. В программировании, списки довольно распространенная вещь. Поэтому, давайте разберем их подробно. И узнаем, как эти списки выглядят, как их создавать и что именно они делают.\r\n\r\n1. Введение в списки:\r\n\r\nНачнем с того, что список в программировании называется “List”. List означает “список” по-английски. Очевидно, правда? Ну так вот, списки хранят данные (значения) с разным форматом(типом), например строки, числа, и т. д. Каждое такое значение в списке имеет свой порядковый номер. Этот номер называется индексом. Индекс нужен для того, чтобы программа поняла, о каком именно значении в списке идет речь.Давайте посмотрим, как выглядит список с различными значениями, на примере кода:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"]\r\nprint(счет)\r\n\r\nЗапишите этот код в файл 5.py и выведите его в терминале с помощью функции print, запустив файл на исполнение  в редакторе VS Code командой \r\npython 5.py. \r\nЧто мы можем узнать про списки в Python из этого примера? Во-первых, в начале и конце списка должны стоять квадратные скобки “[ ]”; Во-вторых, значения в списке разделяются запятой; В-третьих, значения в списке имеют разный формат. Тут мы можем видеть и строки и числа и др.; \r\nТакже можем воспользоваться для создания списка функцией list(). В этом случае аргументами функции передаются элементы списка. Особенно удобно воспользоваться функцией list () для создания списков на основе текстовых значений: если аргументом функции list() передать текст, то в результате получим список, элементы которого - буквы, формирующие текст. Так, при выполнении команды:\r\n\r\n a = list (\"Python\")\r\n print(a)\r\n\r\nсоздается присваивается переменной a список из букв - [\'P\', \'y\', \'t\', \'h\', \'o\', \'n\']. Список может быть и более \"изысканным\": скажем, командой data = [\"t e x t \" ,100, [ 5 , 10]] создается список data из трех элементов, причем первый элемент списка - это текст \"text\", второй элемент списка - целое число 100 , а третий \r\nэлемент - список из двух элементов [5 , 10].\r\n\r\n2. Индекс списка:\r\n\r\nИ так у каждого элемента(значения) в списке есть свой индекс. И программа использует его, чтобы понять о каком  именно значении из списка идет речь. Обращение к элементу списка выполняется по этому индексу элемента. Элементы индексируются, начиная с нуля (то есть самый первый элемент имеет нулевой индекс). Индекс указывается в квадратных скобках после имени переменной, которая ссылается на список. Обязательно помните о том, что положительный индекс списка вPython начинается с нуля. В программах отчет всегда начинается с нуля. Давайте разложим наш верхний список по элементам с индексами:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"] # наш список\r\nсчет[0] = один\r\nсчет[1] = два\"\r\nсчет[2] = 3\r\nсчет[3] = четыре\r\nсчет[4] = пять((\r\n\r\nА теперь через код:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"] # наш список\r\nprint (счет[0])\r\nprint (счет[1])\r\nprint (счет[2])\r\nprint (счет[3])\r\nprint (счет[4])\r\n\r\nДобавим код в наш файл 5.py, запустим на исполнение. Результат в терминале:\r\n\r\nодин\r\nдва\r\n3\r\nчетыре\r\nпять\r\n\r\nВ этом коде,  мы передали индексы нужных нам значений в функцию print. Для этого в скобках функции мы прописали имя списка, затем открыли квадратные скобки, указали индекс, закрыли квадратные скобки, и закрыли скобку функции. Теперь давайте посмотрим, как нам вернуть более одного значения из списка. Для этого нам нужно перечислить индекс нужных значений через запятую. Вот, как это выглядит:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"]\r\nprint(счет[0], счет[2])\r\n\r\nЭтот код возвращает нам первое значение – строку “один”, и третье значение – целое число “3”. Попробуйте самостоятельно извлечь все остальные значения из нашего списка.\r\n\r\n4. Объединение значений списка:\r\n\r\nКак выполнить объединение значений списка? Помните, как мы объединяли строки знаком +? Мы можем выполнить объединение значений списка таким же способом. Давайте это сделаем:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"]\r\nprint(счет[0] + \", \" + счет[2])\r\n\r\nСмотрите. Здесь мы склеили не только два значения списка. Мы еще и поместили дополнительную строку в виде знака запятой между этими значениями. Давайте пойдем немного дальше, и добавим еще одну строку для того, чтобы у нашего списка появилось название:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"]\r\nprint(\"Счет: \" + счет[0] + \", \" + счет[2])\r\n\r\nЗапишите эту программу в редактор и запустите ее. Посмотрите, как список преобразился. А затем поэкспериментируйте с ним. Попробуйте склеить что-нибудь еще, и добавьте в список новые значения.\r\n\r\n5. Функции списка:\r\n\r\nДавайте посмотрим, что такое функции списка в Python, и для чего они нужны? Со списком можно работать по-разному. Можно не только извлекать из него значения, но и, например, считать количество значений в списке. Для этого программисты используют различные функции списка. Функций списка довольно много. Давайте познакомимся с некоторыми из них.\r\n\r\n6. Функция len:\r\n\r\nЧто такое Функция len, и для чего она нужна? len() – это сокращенное название от слова length, что переводится с английского как \r\n“длина”. И делает она именно то, чем она и названа, возвращает нам длину списка. Это удобно, если нам нужно подсчитать количество значений в списке. То есть, узнать его длину. Мы уже знаем, что длина нашего списка – 5 значений. Давайте это проверим при помощи функции len(). Вот, как это делается:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"]\r\nprint(len(счет))\r\n\r\nЗапишите эту программу в файл, и запустите ее. У Вас тоже получилось число 5? А теперь все по порядку:\r\nВ этом коде, на второй строчке, мы поместили название функции len в скобки другой функции (print).\r\nЗатем открыли скобки функции len, и поместили туда имя списка. Затем закрыли скобки функции len, и закрыли скобки функции print.\r\nВот мы и разобрались с тем, как работает функция len в Python.\r\n\r\n7. Функция append:\r\n\r\nДавайте теперь узнаем о том, что такое функция append, и для чего она нужна. Append() переводится с английского как “добавлять в конец”. И это именно то, что эта функция и делает: она добавляет значения в конец нашего списка.Давайте теперь что-нибудь добавим в наш список:\r\n\r\nсчет = [\"один\", \"два\", \"3\", \"четыре\", \"пять\"]\r\nсчет.append(\"шесть\")\r\nprint(счет)\r\n\r\nВ этом коде на второй строчке мы указали название нашего списка, затем поставили точку, и без пробела прописали имя функции append. Затем открыли скобки функции, и вставили туда шестое значение – строку “шесть”. После чего закрыли скобки. Спустились на строчку ниже, и прописали функцию print, указав в скобках функции имя нашего списка. Готово! Теперь у нас целых шесть значений в списке- \r\n[\'один\', \'два\', \'3\', \'четыре\', \'пять\', \'шесть\']!  Вот, как работает функция append в Python.  Запишите этот код в файл 5.py, и запустите его. А затем добавьте в наш список самостоятельно еще несколько значений, используя функцию append.\r\n\r\n8. Объединение списков в Python:\r\n\r\nА теперь мы научимся выполнять объединение списков в Python. Помните, мы говорили о том, что в списках можно хранить любые типы данных?\r\nЭто действительно так. В списках мы можем хранить не только строки и числа, но и другие списки! Давайте создадим два списка. Один с героями Marvel, другой с героями DC . Затем создадим третий список, который будет объединять в себе оба списка. Вперед!\r\n\r\nmarvel = [\"Iron Man\", \"Thor\", \"Captain America\", \"Hulk\"]\r\nDC = [\"Superman\", \"Batman\", \"Wonder Woman\", \"Aquaman\"]\r\nгерои = [marvel, DC]\r\nprint(герои)\r\n\r\nЗапишите этот код в файл, и запустите его. Посмотрите, что получилось. А теперь давайте пойдем еще дальше. Извлечем героя “Batman” из третьего списка! Вот, как это можно сделать:\r\n\r\nmarvel = [\"Iron Man\", \"Thor\", \"Captain America\", \"Hulk\"]\r\nDC = [\"Superman\", \"Batman\", \"Wonder Woman\", \"Aquaman\"]\r\nгерои = [marvel, DC]\r\nprint(герои[1][1])\r\n\r\nДавайте разберем этот пример в деталях:Индекс списка marvel = 0, индекс списка DC = 1. Индекс значения “Batman” в списке DC \r\nтоже равен 1. Потому что он второй в списке. Помните о том, что индекс начинается с нуля? А, значит, чтобы извлечь нашего Бэтмена из списка DC, нам потребовалось дважды указать [1]. Один для списка (DC) и еще один нужного значения в списке (Batman). Вот, как работает объединение списков в Python. Запишите этот код в файл, и запустите его. А затем поиграйте с ним. Добавляйте других героев. Создавайте другие списки, и объединяйте их. \r\n\r\n9. Кортежи:\r\n\r\nВ английском языке кортеж называется Tuple (тюпл). Кортежи очень похожи на списки. Но имеют несколько отличий:\r\n\r\n1) Кортеж весит меньше, чем список.\r\n\r\nКортеж будет весить меньше, чем список с тем же количеством данных. Это особенно полезно в том случае, когда речь идет о программах с большим объемом данных, которые нужно упорядочено хранить. Чем меньше весит приложение, тем быстрее (скорее всего) оно будет работать. Тем быстрее \r\nВы его скачаете. Тем меньше интернет-трафика Вы потратите на его скачивание. И тем меньше памяти это приложение займет на Вашем компьютере или телефоне.\r\n\r\n2) Программа обрабатывает кортеж быстрее, чем список.\r\n\r\nПрограмма быстрее найдет нужное Вам значение в кортеже, чем в списке. Даже если они содержат одинаковое количество данных. Пользователям Ваших будущих программ и видеоигр вряд ли понравится ждать, пока Ваша программа или видеоигра найдет нужную информацию, или отреагирует на их команду. Не так ли?\r\n\r\n3) Кортеж является неизменным типом данных.\r\n\r\nПомните, как мы меняли список, используя функцию append? Таким образом мы меняли оригинал списка. С кортежем такой фокус не пройдет. Если мы внесем изменение в кортеж, то мы лишь изменим его копию, но не оригинал.Таким образом, если к созданному списку программа имеет доступ для чтения и изменения, то, к кортежу программа имеет доступ только для чтения. Такое свойство кортежа не так уж и плохо. Ведь оно защищает кортеж от случайных изменений.\r\n\r\n4) Кортеж отличается от списка синтаксисом.\r\n\r\nТеперь, когда мы поняли чем отличаются кортежи от списков, давайте запишем какие нибудь-данные в кортеж! Для этого мы просто возьмем один из наших предыдущих списков, и превратим его в кортеж:\r\n\r\nmarvel = (\"Iron Man\", \"Thor\", \"Captain America\", \"Hulk\")\r\nprint(marvel)\r\n\r\nЗапишите эту программу в файл, и запустите ее в редакторе. Как Вы видите, внешне кортежи похожи на списки. За исключением того, что они быстрее, легче, неизменны, и имеют круглые скобки вместо квадратных. В остальном все работает, как в случае со списком. Например, мы можем легко извлекать значения из кортежей. Таким же способом,каким мы это делали со списками.\r\n\r\n10. Как превратить кортеж в список?\r\n\r\nХоть мы и “превратили” список в кортеж всего лишь изменив квадратные скобки на круглые, программисты делают это по другому. И список, и кортеж – оба являются типами данных. И для того, чтобы изменить тип данных кортеж, на тип данных список, программисты используют функцию списка. Эта функция называется list. Мы уже говорили о функциях списка выше, и применяли некоторые из них. Давайте теперь применим и функцию list. Она и поможет нам превратить кортеж в список. Как мы уже знаем, list переводится с английского как “список”. И это именно то, что и делает эта функция. Превращает наш кортеж в список:\r\n\r\nmarvel = (\"Iron Man\", \"Thor\", \"Captain America\", \"Hulk\")\r\nсписок = list(marvel) # функция для превращения в кортеж\r\nprint(список)\r\n\r\nСначала мы создали кортеж, и сохранили его в переменной “marvel”. Затем мы превратили кортеж в список, поместив название “marvel” в круглые скобки функции list(). И сохранили новый список в переменной “список”. Затем вывели содержание списка на экран при помощи функции print().\r\nЗапишите этот код в файл, и запустите его. Проверяйте результат:\r\n\r\n[\'Iron Man\', \'Thor\', \'Captain America\', \'Hulk\']\r\n\r\nТот факт, что значения, которые она вывела, находятся в квадратных скобках, говорит о том, что это список. Ну как? Правда, не сложно превращать кортежи в списки, используя Python?\r\n\r\n11. Как наоборот превратить список в кортеж?\r\n\r\nИтак, как нам теперь преобразовать список в кортеж? Точно так же, как мы преобразовали кортеж в список, но на этот раз с помощью функции tuple(). Вот, как мы это сделаем:\r\n\r\nmarvel = [\"Iron Man\", \"Thor\", \"Captain America\", \"Hulk\"]\r\nкортеж = tuple(marvel)\r\nprint(кортеж)\r\n\r\nДавайте рассмотрим этот пример поподробнее. На этот раз мы создали список, и сохранили его в переменной “marvel”. Затем мы превратили список в кортеж, поместив название “marvel” в круглые скобки функции tuple(). И сохранили новый кортеж в переменной “кортеж”. Затем, мы вывели содержание кортежа на экран при помощи функции print() Запишите эту программу в компилятор, и проверьте результат. Вы видите круглые скобки на экране? Это означает, что мы успешно превратили список в кортеж. Как Вы поняли, превращать кортеж в список также легко, как и превращать список в кортеж.\r\n\r\nГЛАВА ДЕВЯТАЯ: СЛОВАРИ\r\n\r\nСловари в Python очень похожи на списки и кортежи. Только они не используют индекс значений. Вместо этого они используют пары, состоящие из ключа и значения. Для того, чтобы понять о чем идет речь, просто представьте себе обыкновенный языковой словарь. Допустим, мы вязли англо-русский словарь. Открываем его, и видим английское слово “hello” (это ключ) и его значение на русском “привет” (это значение ключа).Вот, как выглядит словарь в Python:\r\n\r\nперсонажи = {\"Batman\": \"Первый игрок\", \"Superman\": \"Второй игрок\"}\r\nprint(персонажи) # выводим словарь\r\n\r\nВидите? Для того, чтобы создать словарь, нам всего лишь нужно:  Прописать пару: ключ-значение, между которыми стоит двоеточие; Поместить пару в \r\nфигурные скобки; Если пар несколько, разделить каждую пару запятой; И сохранить полученный словарь в переменной. Запишите эту программу в файл, запустите ее в редакторе и посмотрите, что она выдаст.\r\n\r\n1. Формат словаря в Python:\r\n\r\nКак Вы заметили из прошлого примера, и ключ, и значение всловаре имеют формат строк. Но, мы можем использовать разные форматы внутри одной пары. Например, ключом может быть строка, а значением число. Или наоборот. Давайте создадим новый словарь, в которой ключом будет строка, а значением целое число:\r\n\r\nчисла = {1: \"один\", 2: \"два\"}\r\nprint(числа)\r\n\r\nЗапишите эту программу(код) в файл, и запустите его в редакторе. Посмотрите, какими получились пары словаря.\r\n\r\n\r\n2. Добавление пар в словарь:', 'photos/2026/$m/11/programmist-12.jpg', '2026-06-28 07:49:19.542841', '2026-07-11 11:19:42.808323', 1, 3),
(24, 'Функции', 'phunkcii', 'Функции в Python Вам уже немного знакомы. C некоторыми из них мы уже сталкивались ранее, но это были встроенные в Python функции. Здесь мы узнаем, как создавать собственные функции(пользовательские). Также мы освоим основные приемы по использованию функций в программных кодах.\r\n\r\n\r\n\r\n1. Введение в функции:\r\n\r\nФункция нашего желудка – переваривать пищу. Функция наших глаз – видеть все, что нас окружает. А функция сторожевой собаки – охранять территорию. В компьютерном коде, как мы убедились, тоже могут быть функции. Много функций. Например, есть встроенная функция,  которая выводит информацию на экран. Называется эта функция print(). Вы ее уже хорошо знаете. А еще Вы знаете функцию list(), которая превращает кортеж в список. И функцию tuple() которая, наоборот, превращает список в кортеж(). Функции в Python бывают встроенными и пользовательскими. Встроенные (build in), такие как print(), list(),  tuple() уже есть в Python. И мы просто можем ими пользоваться. Пользовательские (custom) функции – это те функции, которые мы можем создать сами. Если нам не хватает встроенных функций. Для того, чтобы создать такую функцию, нам необходимо использовать ключевое слово def.  def – сокращение от define, что в переводе с английского \r\nозначает “определить”. А значит, когда мы создаем функцию, мы тем самым “определяем” ее обязанности. Давайте посмотрим как это выглядит на примере кода:\r\n\r\ndef поздоровайся():\r\n….print(\"Привет!\")\r\nпоздоровайся()\r\n\r\nСоздадим в редакторе новый файл — 6.py для изучения функций. Вставим в него код и запустим файл на исполнение. Получилось вывести сообщение \"Привет!\" на экран? Отлично! А теперь, давайте разбираться. Сначала мы прописали ключевое слово def. Затем прописали имя функции “поздоровайся”, поставили круглые скобки и двоеточие. Далее мы спустились ниже и сделали 4 отступа. На этой новой строчке мы \r\nсказали нашей функции, что она должна делать. То есть выводить строку “Привет!”. Для этого мы применили встроенную функцию print() и поместили строку “Привет!” в ее круглые скобки. После чего  ниже прописали имя нашей созданной функции  вместе с круглыми скобками. Это называется “вызвать функцию”. Если с этим все понятно, давайте перейдем к параметрам и аргументам функций.\r\n\r\n2. Параметры и аргументы функций:\r\n\r\nНастало время поговорить про параметры и аргументы функций.Как Вы заметили, сразу после имени функции и ее вызова идут круглые скобки. Их необязательно оставлять пустыми. В скобки, стоящие сразу после имени функции, можно поместить параметр функции. А в скобки, стоящие после вызова функции, можно поместить аргумент функции. Давайте посмотрим на пример ниже. Чтобы понять, где параметры, а где аргументы функций в Python:\r\n\r\ndef поздоровайся(имя):\r\n….print(\"Привет, \" + имя + \"!\")\r\nпоздоровайся(\"Илон Маск\")\r\n\r\nСлово “имя”, стоящее в скобках после поздоровайся – это параметр. А строка “Илон Маск”, стоящая в скобках после вызова функции – это аргумент. Вы спросите, в чем разница междупараметром и аргументом? И зачем они нам оба нужны? Параметр – это место, приготовленное для вставки будущего значения. А аргумент – это и есть то значение, которое пришло на место, которое приготовил параметр. Другими словами, \r\nпараметр – это просто заполнитель. А аргумент – это то, что помещается в заполнитель. А теперь запишите этот код в файл 6.py и запустите его.\r\n\r\ndef поздоровайся(имя):\r\n….print(\"Привет, \" + имя + \"!\")\r\nпоздоровайся(\"Илон Маск\")\r\n\r\nДавайте разберем его подробно:\r\nМы поместили параметр под названием имя в круглые скобки функции. Строчкой ниже мы склеили строки “Привет, ” и “!” с именем параметра. Теперь мы можем вызвать функцию, и передать ей аргумент с любым значением. В нашем случае это строка “Илон Маск”. Если с этим все понятно, потренируйтесь, замените “Илон Маск” на другое имя. И перезапустите код. Так Вы измените аргумент, подставив в него новое значение\r\n\r\n.3. Как вернуть значение из функции::\r\n\r\nВозврат значений из функций – это обычная задача для программиста. Давайте научимся \r\nэто делать. Для того, чтобы функция поняла, что ей нужно возвращать значение, нам \r\nнеобходимо использовать ключевое слово return, а затем прописать само значение.\r\nreturn в переводе с английского означает “возвращать”. Для того, чтобы Вам было понятно \r\nкак все это выглядит, создадим функцию под названием “терминатор”. И ее обязанность – \r\nвозвращать нам сообщение “Я еще вернусь…”\r\n\r\ndef терминатор(слова):\r\n….return \"{}\".format(слова)\r\nсообщение = терминатор(\"Я еще вернусь…\")\r\nprint(сообщение)\r\n\r\nДобавьте  этот пример в наш файл, и запустите его. Давайте внимательно его разберем:\r\nСначала мы прописали ключевое слово def. И назвали нашу функцию “терминатор”.\r\nЗатем мы открыли круглые скобки, и передали в них параметр под названием “слова”.\r\nСтрокой ниже мы прописали ключевое слово return. А после return мы создали \r\nформатированную строку (помните эту тему?)\r\nТак у нас получилась функция, которая возвращает значение при помощи форматированной\r\nстроки. Затем мы спустились и “вызывали” функцию терминатор, прописав ее. Затем, в \r\nкачестве аргумента, мы передали ей строку “Я еще вернусь…” И после этого мы сохранили \r\nвызов функции со значением “Я ещевернусь…” в переменной “сообщение”. Наконец, мы \r\nспустились на строчку ниже, и вывели сообщение на экран. Поработайте с этим кодом. \r\nМеняйте название функции, аргументов и значений. \r\n\r\n4. Вложенные функции:\r\n\r\nМы научились создавать пользовательские функции. Давайте теперь научимся создавать вложенные функции, и вложим одну функцию в другую. Вот, как мы это сделаем:\r\n\r\ndef поздоровайся(имя):\r\n….print(\"Привет, \" + имя + \"!\")\r\ndef сообщение(имя, вопрос):\r\n….поздоровайся(имя)\r\n….print(\"Скажи, \" + вопрос)\r\nсообщение(\"Илон\", \"когда летим на Марс?\")\r\n\r\nПеред тем, как мы рассмотрим этот пример во всех подробностях, запишите его в файл 6.py и запустите. Прочитайте в терминале ответ программы и подумайте, как мы его получили? А теперь давайте рассмотрим наш код поподробнее. Мы создали функцию под названием “поздоровайся”, и передали ей “имя” в параметр. Ниже мы вывели строки “Привет, ” и “!”, и соединили их с параметром функции “имя”. В строчке еще ниже создали еще одну функцию под названием “сообщение”. Затем передали ей параметр первой функции (имя) и новый параметр (вопрос). Ниже мы вложили первую функцию во вторую, объявив имя-название первой функции с ее параметром \"вопрос\". На следующей строчке  мы вывели строку “Скажи, ” \r\nи соединили ее со вторым параметром функции. И, наконец, в последней строчке  мы вызвали вторую функцию, передав в ее аргумент значения для параметров первой - \"Илон\" и второй функции - \"когда летим на Марс?\". Итак результат в терминале:\r\n\r\nПривет, Илон!\r\nСкажи, когда летим на Марс?', 'photos/2026/$m/29/4.jpg', '2026-06-28 13:42:01.847268', '2026-06-29 12:26:35.426698', 1, 3),
(25, 'Обработка исключительных ситуаций', 'isclucheniy', 'Какой бы классный программный код ни создавался, \"обойти\" все \"опасные места\" и предусмотреть все возможные варианты развития ситуации далеко не всегда удается. Особенно эта проблема актуальна, когда в программе часть данных считывается из файла или вводится в программу пользователем уже в процессе выполнения программы. В этих случаях велика вероятность получения программой некорректных данных. В таких случаях при выполнении программы могут возникать ошибки, что может привести к преждевременному - \"аварийному\" завершение программы  В Python существует механизм, который позволяет программе выполняться даже после того, как возникла ошибка. Все это называется общим  термином: обработка исключительных ситуаций. Ошибки, связанные с неправильно набранным кодом выявляются просто при попытке запуска  на выполнение программы , скорее всего, будет выведено сообщение о месте ошибки и причине ее возникновения.  Сложнее с ошибками, связанными  с тем, что программа как таковая составлена неправильно. Понятно, что далеко не для каждой ошибки можно выполнить обработку так, чтобы программа продолжала выполняться. Однако в некоторых случаях такая обработка может быть выполнена.\r\nОбщая идея, заложенная в основу метода обработки исключительных ситуаций, такая: программный код, в котором теоретически может возникнуть ошибка, выделяется специальным образом. В Python используется конструкция try - except . Существуют разные вариации использования этой конструкции. Мы рассмотрим   наиболее простые ситуации.\r\nПоступают следующим образом: после ключевого слова try и двоеточия размещается блок программного кода, который мы подозреваем на предмет возможного возникновения ошибки. Этот код будем называть  основным. По завершении этого блока указывается ключевое слово except (с двоеточием), после которого идет еще один блок программного кода. Этот код будем называть вспомогательным или кодом обработки исключения. То есть шаблон такой:\r\n\r\ntry:\r\n\r\n.... # основной код\r\n\r\nexcept:\r\n\r\n.... # вспомогательный код\r\n\r\nЕсли при выполнении основного кода в блоке try ошибка не возникла, то вспомогательный программный код в блоке except выполняться не будет.\r\nЕсли при выполнении основного кода в блоке try возникла ошибка, то выполнение кода try -блока прекращается, и выполняется вспомогательный\r\nкод в блоке except . После этого управление передается следующей команде после конструкции try - except. Пример использования конструкции try-except:\r\n\r\nprint(\"Решаем уравнение ax = b\")    \r\n# Начало try-блока (основной код)                                                           \r\ntry :\r\n....#Определяем первый параметр. Возможна ошибка   при преобразовании текста в число                                                                                        ....a = float(input(\"Введите а: \"))  \r\n....# float- функция для преобразования типов данных\r\n....# Определяем второй параметр. Возможна ошибка.\r\n....# Преобразование текста в число\r\n....b= float(input((\"Введите b: \"))                                                                                   \r\n....# Решение уравнения. Возможна ошибка при делении на ноль ( если введется ноль- так как делить на ноль нельзя)\r\n....x=b/a\r\n....# Выводим результат решения уравнения- команда выполниться если не возникли ошибки                                                                                                                                                    \r\n....print(\"Решение уравнения: x =\", x)                                                                               \r\n# Начало except- блока(вспомогательный код)                                                                                      \r\nexcept :\r\n....# Команда выполнится только если ранее при выполнении основного кода возникла ошибка                                                   \r\n....print(\"Вы ввели не корректные данные!\") #про отступы 4 пробела не забываем                                                        \r\n# Нижняя команда выполняется после блока try-except                                 \r\nprint(\"Спасибо. Работа программы завершена.\") \r\n\r\nДобавим код в файл 6.py запустим его на выполнение командой python 6.py.\r\nРезультат при правильном введении значений (например: a = 10, b = 2):\r\n\r\nРешаем уравнение ax = b \r\nВведите а: 10 \r\nВведите b: 2 \r\nРешение уравнения: x = 0.2 \r\nСпасибо. Работа программы завершена.\r\n\r\nРезультат при не корректном введении значений (например: a = 0, b = 2)\r\n\r\nРешаем уравнение ax = b\r\nВведите а: 0 \r\nВведите b: 2 \r\nВы ввели не корректные данные! \r\nСпасибо. Работа программы завершена.', 'photos/2026/$m/29/25.png', '2026-06-29 13:56:28.135645', '2026-07-09 18:13:50.378841', 1, 3),
(26, 'Классы и объекты', 'classi', 'Классы и объекты – одни из самых важных понятий. \r\n\r\n1. Введение в классы и объекты:\r\n\r\nPython – это объектно-ориентированный язык программирования. Это означает что, все, что мы до сих пор создавали с вами, является объектами. А что такое классы? Класс – это шаблон, по которому создаются  все объекты. А объекты это – экземпляры класса. Давайте посмотрим все на примере:\r\n\r\nБаскетболист Стефен Карри – это объект (или экземпляр) класса “Баскетболист”. Класс “Баскетболист” создает свои объекты по шаблону, в котором указаны свойства и функции этого класса. Эти свойства и функции класс передает своим объектам по наследству:\r\n\r\nСвойства класса “Баскетболист”:\r\nРуки = 2;\r\nНоги = 2;\r\nРост > 1.9 м ;\r\nИ т.д.\r\n\r\nФункции класса “Баскетболист”:\r\nПередвигаться по баскетбольной площадке;\r\nБросать мяч в корзину;\r\nОтбирать мяч у соперника;\r\nПринимать мяч;\r\nПасовать мяч;\r\nИ т.д.\r\n\r\nЕсли с этим пока все понятно, давайте узнаем, как создать класс. Да, и еще кое-что: по ходу дальнейших объяснений мы будем рассматривать примеры кода, которые нужно писать вместе со мной, для того, чтобы создать полноценный класс и объект. Просто смотрите объяснения и пишите код вместе со мной, не запуская его. Как только настанет время запускать наш код, мы его запустим. Итак, поехали!\r\n\r\n2. Как создать класс в Python?:\r\n\r\nДопустим, мы делаем игру. И нам необходимо создать соперников (rival по-английски).\r\nУ соперников функции и свойства одинаковые. А, значит, мы можем объединить их под одним классом “rival”. Для того, чтобы создать класс, необходимо использовать ключевое слово class. Так Python поймет, что мы создаем класс. Итак, создаем класс под названием Rival:\r\n\r\nclass Rival:\r\n\r\nСоздайте в редакторе файл 8.py и запишите пока этот фрагмент в кода в него . Сейчас мы научимся создавать свойства класса\r\n\r\n3. Свойства класса:\r\n\r\nПусть у соперника будет 3 жизни. Давайте для этого, прямо под классом, создадим переменную жизнь (life) со значением 3. Это и будет свойство класса Rival.\r\n\r\nclass Rival:\r\n….life = 3\r\n\r\nТеперь нам необходимо создать функцию класса Rival. Давайте сделаем это.\r\n\r\n4. Функции класса в Python:\r\n\r\nОдна из функций нашего соперника – принимать нашу атаку. Для этого создаем функцию класса под названием атака (attack). Мы уже создавали функции, применяя ключевое слово def. Здесь поступаем так же. Пишем def, затем имя функции, открываем скобки и передаем аргумент (self).\r\nВот, как это выглядит в нашем примере:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n\r\n“А что за self? Мы такое не проходили” Скажите Вы, и правильно сделаете. Self – это обязательное ключевое слово в Python, которое записывается в аргумент функции класса. Позже, когда мы создадим объект класса, мы свяжем этот объект со своим классом именно через self. Вы это увидите на примере, и сразу все поймете. А сейчас вернемся к функции. Итак, мы создали функцию атаки (attack). Теперь скажем программе, что эта функция делает, а делает она вот что: Каждый раз, когда она срабатывает, наш соперник будет кричать“Ouch!” Для этого в теле функции мы прописываем строку “Ouch!”, и передаем ее в аргумент функции print(). Вот, как это выглядит в нашем примере:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n\r\nОбратите внимание на отступы, которые мы делаем в коде: Свойство класса – life и функция класса – attack помещаются в тело класса Rival с использованием четырех отступов. При этом у функции тоже есть свое тело, и мы помещаем в него print(“Ouch!”), делая еще четыре отступа. Так Python понимает к какому классу относятся свойства и функции. А еще так наш код выглядит более аккуратным и понятным.\r\nА теперь вернемся к функции класса:\r\nКаждая наша атака должна не только заставлять соперника кричать “Ouch!”, но и отнимать у него по одной жизни. Для этого из значения переменной life нужно вычитать по одной единице. Но, для того чтобы получить доступ к этой переменной класса, нам нужно прописать self и поставить точку. Так Python поймет, что внутри этого класса мы хотим отнять одну единицу в переменной life.\r\nИ вот, как это будет выглядеть в нашем примере:\r\n\r\nclass Rival:   \r\n….life = 3\r\n\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n\r\nТеперь функция атаки класса (attack) не только заставляет соперника кричать “Ouch!”, но и отнимает у него одну единицу жизни, каждый раз, когда мы его атакуем. Теперь предлагаю создать еще одну функцию класса, которая будет считать количество жизней соперника после каждой нашей атаки. Для этого спускаемся на две строчки ниже, и делаем то же, что и при создании предыдущей функции. А именно: пишем def, затем название этой функции (назовем новую функцию “checkLife”), и передаем ключевое слово self в ее аргумент. Вот, что у нас получится на выходе:\r\n\r\nclass Rival:\r\n….life = 3\r\n\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n\r\n….def checkLife(self):\r\n\r\nИтак, функцию мы прописали. Теперь давайте скажем программе, что делает эта функция. Для этого мы воспользуемся условными заявлениям, с которыми работали выше. Условные заявления для нашего класса:\r\nЕсли количество жизней соперника будет меньше или равно нулю, функция выведет сообщение от имени соперника “You win!” (Вы победили!) А если у соперника еще остались жизни, функция просто скажет,\r\nсколько жизней осталось. Итак, сначала первое условие, в котором мы победили. Вот, как мы это условие пропишем:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0: # условие\r\n…………print(\"You won!\")\r\n\r\nНаш код становится немного сложнее, поэтому давайте подробно рассмотрим то, как мы создали это условие: Под именем функции “checkLife”, после четырех отступов, мы прописали условный оператор if, поставили точку, и прописали ключевое слово self, чтобы программа снова поняла, что мы обращаемся к переменной life, класса Rival. Затем мы прописали оператор сравнения меньше или равно (<=), поставили ноль и двоеточие. Теперь нам надо создать инструкцию, которую программа запустит, если прописанное нами условие сработает. Для этого мы спустились ниже, снова четыре отступа. И приказали программе вывести сообщение “You won!”. Для этого мы передали строку “You win!” в аргумент функции print(). Готово! Теперь, если количество жизней соперника меньше или равно нулю, функция выведет сообщение “You won!” от имени соперника. Если с этим все понятно, давайте создадим второе условие, на тот случай если у нашего соперника еще остались жизни. И зададим соответствующую инструкцию на этот случай\r\n\r\n#Второе условие для нашего класса:\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You win!\")\r\n……..else:\r\n…………print(self.life)\r\n\r\nДавайте снова рассмотрим подробно, что мы только что сделали: Мы спустились еще на одну строку и присвоили условный оператор else. Затем в следующей строке нужно было написать инструкцию для отображения оставшегося количества жизней. Для этого мы назначили функцию print, и передали в ее аргумент ключевое слово self и имя переменной (life). Опять же, нам нужно self, чтобы программа знала, что мы имеем в виду переменную класса. Ну вот! Мы создали простой класс Rival, где у нашего соперника три жизни. И где в ответ на каждую нашу атаку он кричит “Ouch!”, теряя по одной жизни. А еще наш класс умеет считать и выводить количество оставшихся жизней после каждой атаки. И в случае, если жизней не осталось,торжественно выводит сообщение “You win!” У нас получился довольно хороший класс. Давайте же теперь создадим объекты класса!.\r\n\r\nКак создать объект класса в Python:\r\n\r\nСоздание объектов класса очень похоже на создание переменной. Создавая объект класса, нам необходимо дать нашему объекту название. Поскольку класс у нас называется “соперник (Rival)”, то название объекта этого класса будет носить имя какого-нибудь злодея. Поэтому, давайте назовем наш объект в честь Таноса (thanos) из Marvel. Достойный экземпляр соперника. Итак, приступим:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You win!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival() # название  объекта\r\n\r\nКак Вы видите, мы сначали указали имя объекта — thanos. После чего поставили знак равно, и указали название класса, к которому относится наш объект. Далее мы просто добавили к имени класса круглые скобки. Ничего сложного. Теперь давайте присвоим объекту функцию класса, которая отвечает\r\nза подсчет жизни (checkLife). Это позволит нашему объекту thanos проверить количество жизней\r\nперед схваткой. Вот, как это выглядит в нашем примере:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You win!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival()\r\nthanos.checkLife()\r\n\r\nДавайте посмотрим, что мы сделали:\r\nМы спустились на две строки ниже, и прописали имя объекта. После чего поставили точку, и прописали имя нужной нам функции (checkLife), которая уже имеется у нашего класса. Наконец-то настало время запускать наш код! Запустите код, и посмотрите, сколько жизней насчитал у себя thanos\r\nперед схваткой. Если Вы все сделали правильно, программа выдаст Вам цифру 3. Потому что мы задали Таносу три жизни перед схваткой. А теперь в атаку! Давайте атакуем Таноса, и посмотрим, что он нам ответит. Для этого мы спустимся на строчку ниже. Снова пропишем имя объекта thanos, постам точку, и пропишем имя другой,  знакомой нам функции, которую мы создали внутри класса. Это функция attack().\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You won!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival()\r\nthanos.checkLife()\r\nthanos.attack()\r\n\r\nСнова создадим с помощью редактора новый файл(8.py) в папке bin. Вставим в него наш код и запустим \r\nна исполнение. Не забываем вместо точек ставить как положено пробелы. Сколько точек- столько же пробелов. Программа выдаст цифру 3, а под ней сообщение “Ouch!” Откуда взялось сообщение “Ouch!”?\r\n\r\n3\r\nOuch!\r\n\r\nПравильно, от функции print(“Ouch!”), которую мы ранее прописали внутри функции атаки – def attack(self). Помните, да? Хорошо! А сколько у Таноса осталось жизней после нашей первой атаки? Давайте узнаем это. Для этого мы добавим в конец нашего кода еще одну функцию checkLife(). И вот, что у нас получится:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You won!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival()\r\nthanos.checkLife()\r\nthanos.attack()\r\nthanos.checkLife()\r\n\r\n\r\nВнесем изменения в файл 8.py и посмотрим результат. Если Вы все сделали правильно, программа выдаст цифру 3, затем сообщение“Ouch!”, а затем цифру 2:\r\n\r\n3\r\nOuch!\r\n2\r\n\r\nА это значит, что у Таноса осталось две жизни! Мы побеждаем! Предлагаю атаковать нашего соперника еще два раза и посмотреть, кто победит. Наносим решающий удар. Вот секретный код победы над злодеем:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You won!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival()\r\nthanos.checkLife()\r\nthanos.attack()\r\nthanos.attack()\r\nthanos.attack()\r\nthanos.checkLife()\r\n\r\nПримечание: Писать функцию три раза подряд не самая лучшая практика. Для удобства можно применить циклы. Однако в этом примере для  простоты и наглядности, фокус делается на классы и объекты.\r\nИтак, если Вы все сделали правильно, программа выдаст Вам вот такое сообщение:\r\n\r\n3\r\nOuch!\r\nOuch!\r\nOuch!\r\nYou win!\r\n\r\nНу как? Получилось? Отличная работа! Вы только что научились создавать классы и объекты в Python! И даже победили Таноса по пути. Но, тема классов и объектов будет неполной, если мы не узнаем, как управлять разными объектами, принадлежащими одному классу. Давайте узнаем это.\r\n\r\nУправление объектами класса:\r\n\r\nТеперь мы поняли что объект – это, по сути, копия своего класса. Но, даже если несколько объектов и могут относиться к одному классу, между собой эти объекты все равно независимы. Таким образом, если Вы отнимите жизнь у одного соперника (объекта своего класса), то это никак не повлияет на другого соперника (объекта того же класса). На примере реальной жизни это выглядит так:\r\nВы играете в видеоигру, например, в Dota. Перед Вами два соперника: Slark и Axe, которые хотят вступить с Вами в ближний бой. И Slark, и Axe – это объекты одного класса (класс соперников), у них даже есть общие функции, унаследованные от своего класса, например, ближний бой. Но при этом они остаются полностью независимыми друг от друга объектами. Например, у каждого из них разные атрибуты: у Slark – ловкость, а у Axe – сила. А еще у каждого из них отдельная шкала здоровья. Если Вы нанесете урон Сларку, то его шкала здоровья изменится, а шкала здоровья Axe останется без изменений. Восстанавливаться их шкалы тоже могут с разной скоростью. И так далее. Думаю, теперь Вы поняли, что программисты должны уметь управлять объектами класса так, чтобы эти объекты могли оставаться\r\nнезависимыми друг от друга. А раз так, давайте создадим второй объект для нашего класса Rival, и сделаем его независимым от первого объекта. Создаем второй объект класса:\r\n\r\nПервым объектом у нас был злодей thanos. Давайте добавим второй объект-злодея, пусть это будет Магнето (magneto). Затем атакуем Таноса, и посмотрим как это отразится на Магнето.\r\nВот, как это будет выглядеть на примере:\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You win!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival()\r\nmagneto = Rival() # второй объект\r\nthanos.checkLife()\r\nmagneto.checkLife()\r\n\r\nКак Вы видите из примера, мы добавили второй объект, назвав его magneto, и присвоили ему класс “Rival”. Затем, как и в случае с объектом thanos, мы присвоили ему функцию, которая проверяет жизнь: magneto.checkLife() Таким образом, когда программа запускается, оба объекта проверяют и сообщают количество своих жизней. Впишите этот код в компилятор, и запустите его. Если Вы все сделали правильно, программа дважды выведет цифру 3. Потому что и у Таноса, и у Магнето по три жизни.\r\nЗатем давайте атакуем Таноса три раза, после чего оба объекта снова проверят, и сообщат нам количество оставшихся жизней. Для этого, все что нам осталось сделать, – это трижды добавить thanos.attack() в наш код.\r\n\r\nclass Rival:\r\n….life = 3\r\n….def attack(self):\r\n……..print(\"Ouch!\")\r\n……..self.life -=1\r\n….def checkLife(self):\r\n……..if self.life <=0:\r\n…………print(\"You won!\")\r\n……..else:\r\n…………print(self.life)\r\nthanos = Rival()\r\nmagneto = Rival()\r\nthanos.attack()\r\nthanos.attack()\r\nthanos.attack()\r\nthanos.checkLife()\r\nmagneto.checkLife()\r\n\r\nВпишите этот код в наш файл, и запустите его. Если Вы все сделали правильно, программа вернет Вам вот такое сообщение:\r\nOuch!\r\nOuch!\r\nOuch!\r\nYou win!\r\n3\r\n\r\nКак видите, Танос теперь поражен, но у Магнето все еще три жизни. А это значит, что функции класса, которые мы применили к одному объекту, совершенно не влияют на другие объекты того же класса.\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n.', 'photos/2026/$m/09/programmist-10.jpg', '2026-07-09 17:37:14.812483', '2026-07-09 19:15:02.851434', 1, 3);
INSERT INTO `adik_adik` (`id`, `title`, `slug`, `content`, `photo`, `time_create`, `time_update`, `is_published`, `cat_id`) VALUES
(27, 'модули и пакеты', 'moduli', 'Модули в Python, как и в других языка программирования – это файлы, которые содержат код. Программисты применяют модули для повторного использования одного и того же кода в программе.\r\nДавайте узнаем о модулях и пакетах подробнее. Увидим их на примере и научимся с ними работать.\r\n\r\n1. Введение в модули и пакеты:\r\n\r\nМодули в Python могут содержать и переменные, и функции, и другие элементы кода. У Python есть много различных встроенных модулей, которые могут использоваться в разных задачах.\r\nЕсли с модулями пока все понятно, давайте узнаем, что такое пакеты модулей. Пакеты модулей- это, попросту, папки, в которых хранится несколько модулей. Представьте себе папку с файлами. Это и есть пакет модулей. Давайте теперь научимся импортировать модули в наш код.\r\n\r\n2. Как импортировать модуль:\r\n\r\nДля того, чтобы применить модуль, его необходимо импортировать в наш код. И как упоминалось ранее, в Python есть множество встроенных модулей. Давайте выберем один из таких встроенных модулей – модуль datetime, и импортируем его. Модуль datetime и функция date. Модуль datetime делает именно то, как он и называется. Он показывает нам дату и время. И для того, чтобы его импортировать в наш код, нам понадобится команда import и имя самого модуля. Вот, как это выглядит на примере:\r\nimport datetime.\r\nДа, и еще кое-что: импортируя модули в Ваш код, всегда прописывайте команду import и название модуля первыми, сразу в начале кода. Как Вы помните, программа читает код сверху вниз. И если в коде есть модули, она сразу об этом узнает, и импортирует их для корректной работы всего кода. Вернемся к нашему модулю datetime. У него есть функция date, и она превращает числа в дату. Давайте посмотрим, как это выглядит на примере:\r\n\r\nimport datetime\r\nbirthday = datetime.date(2026, 6, 4)\r\nprint(birthday)\r\n\r\nЗапишите этот код в самом начале файла 8.py( оставив небольшой строчный интервал до «class Rival») и запустите его на исполнение: Как вы заметили, мы вводили числа через запятую. А на экране они вышли через тире. Это произошло благодаря тому, что команда date, модуля datetime, преобразовала наши числа в дату. Получилась вот такая дата: 2026-06-04 - четвертое июня, 2026 года.А теперь давайте разберем этот код по шагово:\r\nСначала мы импортировали модуль datetime, прописав команду import и указав имя модуля. Затем мы спустились на строчку ниже, и прописали (вызвали) модуль datetime, поставили точку, и прописали функцию date. Затем открыли скобки и передали год, месяц и день в аргумент функции date. После чего мы сохранили полученную дату в переменную birthday (день рождения). И, наконец, мы спустились на строчку ниже, и вывели переменную birthday на экран, при помощи функции print.\r\n\r\nМодуль datetime и функция datetime.now:\r\n\r\nДавайте закрепим пройденный пример еще одной функцией модуля. Эта функция называется datetime.now(). И ее задача сообщать нам, какая сейчас дата и время. Давайте напишем маленькую программу, которая сообщит нам, какой сейчас год:\r\n\r\nimport datetime # эта строчка уже вставлена в начале файла, две нижние  ставим в конце файла\r\nx = datetime.datetime.now()\r\nprint(x.year)\r\n\r\nЗапишите этот код в наш файл 8.py, и запустите его. Если Вы все сделали правильно, то программа скажет Вам, какой сейчас год(2026). А теперь снова разберем наш пример:\r\nСначала мы импортировали модуль datetime, прописав команду import и указав имя модуля. Затем мы спустились на строчку ниже, и прописали (вызвали) модуль datetime, поставили точку и прописали функцию datetime.now с пустыми двойными скобками (Пустым аргументом). После этого мы сохранили получившуюся дату (а получилась она благодаря функции datetime.now) в переменную x. И, наконец, спустившись на строчку ниже, мы прописали функцию print, и передали ей аргументы: нашу переменную x и параметр .year. Работая вместе, функция datetime.now и параметр .year (год) определили текущий год. А функция принт вывела его на экран. Здесь хочу сказать, что year – это не единственный параметр, с которым мы можем работать. Есть еще такие параметры, как: month, day, hour, minute, second, которые  определяют соответственно: месяц, день, час, минуту и секунду. Давайте добавим параметры “месяц” и “день” к нашему коду:\r\n\r\nimport datetime\r\nx = datetime.datetime.now()\r\nprint(x.year,x.month,x.day)\r\n\r\nДопишите строки в код нашего файла( можно создать и запустить в новом), и запустите его. Как видите, теперь программа возвращает нам текущий год, месяц и сегодняшнее число - 2026 7 6.\r\n\r\n3. Как импортировать функцию модуля:\r\n\r\nМы можем импортировать не только модуль полностью, но и конкретную функцию модуля. Иногда программисты предпочитают делать именно это, импортировать не весь модуль а только конкретную его функцию. Делают они это для того, чтобы получить больше контроля над функциями модуля в своем коде. А ещё, в случаях, когда импортировать весь модуль необязательно. Если с этим все понятно, давайте импортируем функцию date модуля datetime:\r\n\r\nfrom datetime import date\r\nbirthday = date(2026, 6, 4)\r\nprint(birthday)\r\n\r\nЗапишите этот код в новый файл, и запустите его. Как Вы видите, этот код очень похож на тот, в котором мы импортировали весь модуль datetime. Тут даже вывод программы одинаковый, все та же дата: четвертое июня, 2026 года. Но, в этом коде все же есть некоторые отличия. И вот они:\r\nНа первой строчке сначала ставится ключевое слово from, затем имя модуля, затем команда import, и в конце пишется имя конкретной функции модуля, которую мы хотим импортировать. На второй строчке мы больше не вызываем модуль datetime. Вместо этого мы вызываем только его функцию date. На этом отличия заканчиваются, и далее мы передаем в аргумент функции date год, месяц и день. После чего сохраняем полученную дату в переменную birthday. Спускаемся на строчку ниже, и выводим переменную birthday с помощью функции print.\r\n\r\n4. Имя функции модуля в Python:\r\n\r\nТеперь поговорим про имя функции модуля в Python и его вариации. Дело в том, что когда мы импортируем большое количество функций модуля, одинаковые имена функций могут вызвать путаницу в коде или конфликтовать между собой. К счастью, чтобы решить эту проблему, мы можем изменить имя функции модуля в Python, когда импортируем ее. Для этого мы должны использовать ключевое слово as. Ключевое слово as переводится с английского “как”. Мы, будто сообщаем программе: импортируй эту функцию как “Функция А”, а эту как “Функция Б” Давайте переименуем функцию модуля при ее импорте:\r\n\r\nfrom datetime import date as d\r\nbirthday = d(2017, 6, 1)\r\nprint(birthday)\r\n\r\nЗапишите этот код в файл при помощи редактора, и запустите его. Давайте посмотрим, что мы сделали:\r\nМы взяли наш код из предыдущего задания и просто добавили в него ключевое слово “as” и новое имя “d” после команды import date. На второй строчке мы заменили date на d. Ничего сложного, верно? Потренируйтесь. Переименуйте функцию date по своему вкусу, и перезапустите код.\r\n\r\n5. Как создать модуль в Python:\r\n\r\nИз знакомства с модулями мы узнали, что в Python есть большое количество встроенных модулей. Которые могут использоваться в разных ситуациях. Но как и в случае с функциями, которые бывают встроенными и пользовательскими, модули тоже бывают встроенные и пользовательские.\r\nКогда программисту необходимо создать модуль в Python, они просто записывают фрагмент рабочего кода в файл, дают файлу название, и сохраняют его под расширением .py (сокращенно от python). Затем этот файл сохраняется в той же папке, где хранится файл с основным кодом. Так создается модуль. Теперь, когда программисту требуется его импортировать в свой код, он просто пишет команду import и указывает название файла, в котором сохранил этот модуль.\r\n\r\n6. Пакет модулей в Python:\r\n\r\nКак Вы уже знаете, пакет модулей в Python – это папка, где хранится несколько модулей. Кроме самих модулей в такой папке обязательно должен храниться файл вот с таким названием: __init__.py Он нужен для того, чтобы программа поняла, что это пакет модулей. То есть папка, где хранятся модули.', 'photos/2026/$m/11/operatori.jpg', '2026-07-09 19:32:29.524548', '2026-07-11 11:22:56.506960', 1, 3),
(28, 'Пример программирования игры', 'primer_igri', 'Если Вы дошли до этого момента, значит смогли постичь основы программирования на Python: типы данных и конструкции, которые включают в себя переменные, числа, строки, булеву логику, условные заявления, функции. А также основы объектно-ориентированного программирования, а именно классы, объекты и управление ими. Все это поможет Вам без особого труда понять код нашей игры и его\r\nустройство. А теперь приступим к делу. Ваша задача состоит в том, чтобы ознакомиться с кодом игры, который я приведу ниже, детально изучить каждый из семи этапов его создания, а затем создать свою собственную версию этой игры. Говоря о своей собственной версии, я подразумеваю несколько вариантов. Первый пожалуй самый легкий. В нем Вы можете взять наш код за основу и изменить его по своему вкусу. Например изменить переменные, сделать игру более сложной или более легкой. Второй вариант предусматривает то, что Вы пойдете еще дальше и измените не только переменные, но и сценарий игры. И наконец третий вариант для самых пытливых. В нем Вы можете создать свою собственную игру, пользуясь примером нашего кода! И конечно же, Вы можете воспользоваться всеми вариантами по очереди, по мере роста \r\nвашего навыка в программировании и уверенности в своих силах.\r\n\r\nКод игры:\r\n\r\nВажное напоминание: \r\nТочки в начале строк указывают на отступы, которые ваш  редактор будет ставить автоматически при сохранении. Все, что стоит за знаком # – это комментарии к коду, для Вашего удобства.\r\n\r\nclass SoyuzDocking:\r\n….def __init__(self):\r\n……..self.distance = 500 # Расстояние до \"Салют 7\" в метрах\r\n……..self.speed = 50 # Скорость к \"Салют 7\" в м/с\r\n……..self.fuel = 100 # Количество топлива\r\n# Сжечь топливо для замедления корабля\r\n….def perform_burn(self, burn_amount):\r\n……..self.speed = max(self.speed – burn_amount, 0)\r\n……..self.fuel = max(self.fuel – burn_amount, 0)\r\n# Обновить расстояние на основании текущей скорости\r\n….def update_distance(self):\r\n……..self.distance = max(self.distance – self.speed, 0)\r\n# Проверить, состыковался-ли корабль к Салют-7\r\n….def has_docked(self):\r\n……..return self.distance <= 0\r\n# Создать последовательность стыковки\r\ndocking_sequence = SoyuzDocking()\r\n# Показать инструкции к игре\r\nprint(\"Добро пожаловать в симуляцию стыковки Союз Т-6!\")\r\nprint(\"Ваша миссия – стыковка со станцией Салют-7.\")\r\nprint(\"Вы можете управлять скоростью космического корабля сжигая топливо.\")\r\nprint(\"Каждая единица сожженного топлива замедляет космический корабль на 1 м/с.\")\r\nprint(\"Удачи экипажу!\\n\")\r\n# Главный игровой цикл\r\nwhile not docking_sequence.has_docked():\r\n….print(f\"Расстояние до Салют-7: {docking_sequence.distance} метров\")\r\n….print(f\"Скорость: {docking_sequence.speed} м/с\")\r\n….print(f\"Топливо: {docking_sequence.fuel} кг\")\r\n# Сообщение о провале миссии в случае если закончилось топливо\r\n….if docking_sequence.fuel <= 0:\r\n……..print(\"Кончилось топливо!\")\r\n……..break\r\n# Запрос на активацию автопилота если расстояние до станции менее 11 м\r\n….if docking_sequence.distance < 11:\r\n……..autopilot = input(\"До станции Салют-7 осталось менее 11\r\nметров. Активировать режим автопилота для автоматической стыковки? (да/нет): \")\r\n……..if autopilot.lower() == \'да\':\r\n…………print(\"Автопилот активирован.\")\r\n…………break\r\n# Запрос и ввод количества топлива, которое нужно сжечь\r\n….burn_amount = input(\"Сколько сжечь топлива для снижения скорости: \")\r\n….burn_amount = int(burn_amount)\r\n# Сжигание топлива и обновление расстояния до космическойстанции\r\n….docking_sequence.perform_burn(burn_amount)\r\n….docking_sequence.update_distance()\r\n# Завершение процесса стыковки – проверить условия и вывести результат\r\nif docking_sequence.distance <= 11 and docking_sequence.speed <=\r\ndocking_sequence.distance:\r\n….print(\"Стыковка подтверждена. Поздравляем экипаж!\")\r\nelse:\r\n….print(\"Миссия провалена. Союз Т-6 не смог состыковаться с Салют-7.\")\r\n\r\nЭта игра симулирует процесс стыковки космического корабля Союз Т-6 с орбитальной станцией Салют-7. Ваша задача, как игрока, – успешно состыковаться с космической станцией Салют-7, управляя скоростью космического корабля и эффективно используя ограниченное количество топлива. Игра начинается с того, что Ваш космический корабль Союз находится на расстоянии в 500 метрах от станции и движется к ней со скоростью 50 метров в секунду. Топлива у вас всего 100 килограмм. Ваша задача – контролировать скорость космического корабля, решая, сколько топлива сжечь на каждом ходу. Каждый килограмм сожженного Вами топлива замедляет корабль ровно на один метр в секунду. Есть два обязательных условия для победы в этой игре:\r\nВо первых, Ваш космический корабль должен приблизиться к космической станции достаточно близко (менее 11 метров) для того, чтобы активировать режим автопилота, который и состыкует Ваш корабль.\r\nВо вторых, скорость Вашего космического корабля в секунду не может превышать оставшееся расстояние до космической станции, даже после активации автопилота. Иначе, Вы просто врежетесь в космическую станцию. При этом не забывайте о запасах оставшегося топлива. Вы проигрываете, если космический корабль исчерпает запас топлива до того, как доберется до космической станции. Помните, что исследование космоса требует точности и сообразительности. Успех вашей миссии зависит от того, сделаете ли вы правильные ходы в нужное время. Игра написана на Python с использованием объектно-ориентированного подхода, где SoyuzDocking – это класс, который отвечает за состояния игры и методов взаимодействия с ней. Код игры содержит цикл, который постоянно проверяет состояние игры, получая от игрока ввод и обновляя состояние игры до тех пор, пока игра не закончится. Удачи, космонавт!\r\n\r\nПодсказка к игре:\r\n\r\nКак Вы уже знаете из пройденной книги, в Python класс служит шаблоном для создания объектов. У объектов есть свойства (они также называются атрибутами) и методы. В этой игре у нас есть класс под названием SoyuzDocking. Объект этого класса представляет собой космический корабль \"Союз\", который должен состыковаться с космической станцией Салют-7. Давайте разберемся с определением класса:\r\n\r\nclass SoyuzDocking:\r\n….def __init__(self):\r\n……..self.distance = 500 # Расстояние до \"Салют 7\" в метрах\r\n……..self.speed = 50 # Скорость к \"Салют 7\" в м/с\r\n……..self.fuel = 100 # Количество топлива\r\n\r\nА теперь разберем все на части:\r\n\r\nclass SoyuzDocking: Эта строка начинает определение класса с именем SoyuzDocking.\r\ndef __init__(self): Это метод инициализатора, который автоматически вызывается при создании нового объекта этого класса. Он часто используется для установки начального состояния объекта.После определения этого класса мы можем создать новый объект SoyuzDocking вот таким способом:\r\n\r\n# Создать последовательность стыковки\r\ndocking_sequence = SoyuzDocking()\r\n\r\nВ этой строке, docking_sequence теперь является объектом (экземпляром) класса SoyuzDocking, который отвечает за создание последовательности процесса стыковки. Такой объектно-ориентированный подход позволяет нам моделировать сложные системы (например, процедуру стыковки космического корабля) при этом сохраняя наш код аккуратным и понятным.\r\n\r\nДетально разберем атрибуты класса SoyuzDocking:\r\n\r\nВ предыдущем шаге, в классе SoyuzDocking мы определили три атрибута в методе инициализации:\r\n\r\nclass SoyuzDocking:\r\n….def __init__(self):\r\n……..self.distance = 500 # Расстояние до \"Салют 7\" в метрах\r\n……..self.speed = 50 # Скорость к \"Салют 7\" в м/с\r\n……..self.fuel = 100 # Количество топлива\r\n\r\nА теперь разберем детально, что представляет каждый атрибут:\r\nself.distance = 500: Этот атрибут представляет расстояние в метрах до космической станции \"Салют 7\" в начале игры.\r\nself.speed = 50: Этот атрибут представляет скорость космического корабля в метрах в секунду.\r\nself.fuel = 100: Этот атрибут представляет количество доступного топлива на космическом корабле в начале игры. Эти атрибуты критически важны для нас, поскольку именно они определяют состояние игры.\r\nПо мере прохождения игры эти значения будут меняться в зависимости от действий игрока. Например, каждое сжигание топлива будет уменьшать атрибут топлива и изменять атрибут скорости. А атрибут расстояния будет меняться по мере приближения нашего космического корабля к космической станции.\r\nЕсли с этим все понятно, давайте перейдем к следующему шагу.\r\n\r\nДетально разбираем методы класса SoyuzDocking:\r\n\r\nВ нашем классе SoyuzDocking есть три метода:\r\n\r\nperform_burn()\r\nupdate_distance()\r\nhas_docked().\r\n\r\nДавайте детально их рассмотрим:\r\n\r\n# Сжечь топливо для замедления корабля\r\n….def perform_burn(self, burn_amount):\r\n……..self.speed = max(self.speed – burn_amount, 0)\r\n……..self.fuel = max(self.fuel – burn_amount, 0)\r\n\r\n# Обновить расстояние исходя из текущей скорости корабля\r\n….def update_distance(self):\r\n……..self.distance = max(self.distance – self.speed, 0)\r\n\r\n# Проверить, состыковался-ли корабль к Салют-7\r\n….def has_docked(self):\r\n……..return self.distance <= 0\r\n\r\nperform_burn(burn_amount): Этот метод выполняет сжигание топлива, уменьшая скорость космического корабля и количество оставшегося топлива. Аргумент burn_amount указывает на то, сколько топлива сжечь.\r\n\r\nupdate_distance(): Этот метод обновляет расстояние до космической станции, исходя из текущей скорости корабля.\r\n\r\nhas_docked(): Этот метод проверяет, успешно ли космический корабль состыковался с космической станцией. Если расстояние до космической станции равно 0, он возвращает True, указывая на успешную стыковку. В противном случае возвращает False. Все эти методы определяют действия, которые наш корабль может\r\nвыполнять. А также и условия, при которых корабль может пристыковаться к космической станции.\r\nВызывая эти методы в правильной последовательности и с правильными аргументами, мы можем смоделировать процесс пристыковки к космической станции Салют-7.\r\n\r\nУглубляемся в работу игрового цикла:\r\n\r\nКак Вы уже могли понять к этому моменту, игровой цикл – это конструкция управления потоком игры.\r\nТакая конструкция, кроме самого цикла, содержит некоторые типы данных и элементы, которые Вам уже знакомы. Это: переменные, числа, строки, булева логика, и условные заявления. Она циклически проходит через этапы игры до тех пор, пока не будет выполнено определенное условие. Теперь об условиях. В нашей игре, цикл будет работать до тех пор,пока наш корабль не состыкуется с \"Салют-7\", либо пока не кончится\r\nтопливо. Или же пока мы не врежемся в космическую станцию. Давайте теперь посмотрим на саму конструкцию:\r\n\r\n# Главный игровой цикл\r\n# 1 Выводим информацию о расстоянии, скорости и топливе\r\nwhile not docking_sequence.has_docked():\r\n….print(f\"Расстояние до Салют-7: {docking_sequence.distance} метров\")\r\n….print(f\"Скорость: {docking_sequence.speed} м/с\")\r\n….print(f\"Топливо: {docking_sequence.fuel} кг\")\r\n# 2 Сообщение о провале миссии в случае если закончилось топливо\r\n….if docking_sequence.fuel <= 0:\r\n……..print(\"Кончилось топливо!\")\r\n……..break # остановка работы цикла\r\n# 3 Запрос на активацию автопилота если расстояние до станции менее 11 м\r\n….if docking_sequence.distance < 11:\r\n……..autopilot = input(\"До станции Салют-7 осталось менее 11 метров. Активировать режим автопилота для автоматической стыковки? (да/нет): \")\r\n……..if autopilot.lower() == \'да\':\r\n…………print(\"Автопилот активирован.\")\r\n…………break  # остановка работы цикла \r\n# 4 Запрос и ввод количества топлива, которое нужно сжечь\r\n….burn_amount = input(\"Сколько сжечь топлива для снижения скорости: \")\r\n….burn_amount = int(burn_amount) # преобразуем в числовой тип\r\n# 5 Сжигание топлива и обновление расстояния до космической станции\r\n….docking_sequence.perform_burn(burn_amount)\r\n….docking_sequence.update_distance()\r\n# 6 Завершение процесса стыковки – проверить условия и вывести результат\r\nif docking_sequence.distance <= 11 and docking_sequence.speed <= docking_sequence.distance:\r\n….print(\"Стыковка подтверждена. Поздравляем экипаж!\")\r\nelse:\r\n….print(\"Миссия провалена. Союз Т-6 не смог состыковаться с Салют-7.\")\r\n\r\nКаждая итерация цикла while представляет собой новый ход в игре. На каждом ходу игра:\r\nВыводит текущее расстояние до \"Салют-7\", скорость космического корабля и количество оставшегося топлива. (1) \r\nПроверяет, не закончилось ли топливо у космического корабля. Если это так, то выводит сообщения: \"Кончилось топливо!” и \"Миссия провалена. Союз Т-6 не смог состыковаться с Салют-7.\" После чегозавершает игру. (2)\r\nПроверяет, находится ли космический корабль на расстоянии менее 11 метров от \"Салют-7\". И если это так, то предлагает игроку активировать автопилот. Если игрок решает активировать автопилот, то проверяет – не превышает ли текущая скорость в секунду, оставшегося расстояния до станции. Если нет, то выводит сообщения: \"Автопилот активирован” и “Стыковка подтверждена. Поздравляем экипаж!\" После чего завершает игру. (3) (6)\r\nВ противном случае выводит сообщение: \"Миссия провалена. Союз Т-6 не смог состыковаться с Салют-7.\" После чего завершает игру. (6)\r\nЕсли ни одно из вышеперечисленных условий не выполняется, игра предлагает игроку очередной ход, в котором снова спрашивает игрока о том, сколько топлива сжечь. (4)\r\nВызывает метод perform_burn() объекта SoyuzDocking с вводом количества топлива от игрока для обновления скорости космического корабля и оставшихся запасов топлива. (5)\r\nВызывает метод update_distance() для обновления расстояния космического корабля до \"Салют-7\" исходя из его текущей скорости.(5)\r\nЭтот цикл является основой нашей игры, позволяя игроку взаимодействовать с ней и видеть результаты своих действий. Цикл будет повторяться до тех пор, пока: не будет достигнут результат стыковки, или у космического корабля не закончится топливо, или корабль не врежется в космическую станцию.\r\n\r\nУчимся принимать и обрабатывать ответ игрока:\r\n\r\nВ интерактивных программах, таких, как эта игра, ввод данных от пользователя имеет огромное значение.\r\nВ нашем случае пользовательский ввод – это количество топлива, которое игрок хочет сжечь за данный игровой ход. Вот как выглядит фрагмент нашего кода, который отвечает за прием и обработку пользовательского ввода (ответа игрока):\r\nburn_amount = input(\"Сколько сжечь топлива для снижения скорости: \")\r\nburn_amount = int(burn_amount)\r\nСтрока \"Сколько сжечь топлива для снижения скорости:\", выводит вопрос на экран, а функция input() используется для получения ответа от игрока. Затем функция ожидает, когда пользователь введет свой ответ и нажмет enter. Все, что пользователь вводит (кроме клавиши enter), возвращается функцией в виде строки. В нашей игре мы ожидаем, что пользователь введет число, так как burn_amount представляет собой количество топлива. Однако, поскольку функция input() всегда возвращает строку, нам нужно преобразовать эту строку в число. Это делается сразу после получения ввода:\r\nburn_amount = int(burn_amount)\r\nВы уже знакомы с преобразованием строковых значений. Так вот, здесь функция int() используется для преобразования строки в целое число. При этом, если пользователь вводит что-то, что не может быть преобразовано в число (например, \"пять\" вместо 5), эта строка выдаст ошибку. Пока это все для данного шага. И наша игра теперь принимает ответ от игрока, и использует его для подсчета количества топлива, которое необходимо потратить.\r\n\r\nУчимся выводить сообщения для игрока:\r\n\r\nЗдесь все немного похоже та то, что мы уже делали в предидущем шаге, однако там мы фокусировались на циклах. А здесь – на выводе сообщений для игрока. Итак приступим. Для того чтобы игра была интересной, нам необходимо давать игроку обратную связь, как в начале игры, так и по мере ее прохождения и завершения. Для этого, нам всегда необходимо начинать игру с подробных инструкций, что мы сейчас и сделаем. Этот фрагмент кода выводит пять строк, которые объясняют игроку, что нужно делать. Заметили “\\n” на пятой строке? Этот символ делит текст на параграфы(перевод строки). Он поможет нам визуально отделить нашу стартовую инструкцию от дальнейших сообщений, для удобства игрока:\r\n# Показать инструкции к игре\r\nprint(\"Добро пожаловать в симуляцию стыковки Союз Т-6!\")\r\nprint(\"Ваша миссия – стыковка со станцией Салют-7.\")\r\nprint(\"Вы можете управлять скоростью космического корабля сжигая топливо.\")\r\nprint(\"Каждая единица сожженного топлива замедляет космический корабль на 1 м/с.\")\r\nprint(\"Удачи экипажу!\\n\")\r\n\r\nТри сообщения, которые Вы видите ниже, сообщают игроку оперативные данные: расстояние до космической станции, текущую скорость, и количество оставшегося топлива:\r\n\r\n# Главный игровой цикл\r\nwhile not docking_sequence.has_docked():\r\n….print(f\"Расстояние до Салют-7: {docking_sequence.distance} метров\")\r\n….print(f\"Скорость: {docking_sequence.speed} м/с\")\r\n….print(f\"Топливо: {docking_sequence.fuel} кг\")\r\nДанное сообщение появляется в случае, если у игрока закончилось топливо:\r\n# Сообщение о провале миссии в случае если закончилось топливо\r\n….if docking_sequence.fuel <= 0:\r\n……..print(\"Кончилось топливо!\")\r\n……..break\r\nА это сообщение появляется в случае, если корабль приблизился на расстояние менее 11 метров от станции. Сообщение содержит вопрос об активации автопилота, варианты ответа, и еще одно сообщение, на\r\nслучай если игрок активирует автопилот:\r\n# Запрос на активацию автопилота если расстояние до станции менее 11 м\r\n….if docking_sequence.distance < 11:\r\n……..autopilot = input(\"До станции Салют-7 осталось менее 11 метров. Активировать режим автопилота для автоматической стыковки? (да/нет): \")\r\n……..if autopilot.lower() == \'да\':\r\n…………print(\"Автопилот активирован.\")\r\n…………break\r\nИ наконец, в данном булевой конструкции есть два сообщения: первое на случай если условия для успешной стыковки выполнены. Второе напротив, на случай если такие условия не выполнены:\r\n# Завершение процесса стыковки – проверить условия и вывести результат\r\n\r\nif docking_sequence.distance <= 11 and docking_sequence.speed <= docking_sequence.distance:\r\n….print(\"Стыковка подтверждена. Поздравляем экипаж!\")\r\nelse:\r\n….print(\"Миссия провалена. Союз Т-6 не смог состыковаться с Салют-7.\")\r\n\r\nЧто дальше?\r\n\r\nТеперь, когда Вы постигли азы программирования на Python, Вы можете приступить к самостоятельным проектам. Так, Вы можете начать создавать свои собственные игры и программы, наподобие тех, что мы прошли. Экспериментировать и усложнять их код, делая Ваши игры и программы более функциональными и интересными. Начните собирать собственную коллекцию таких проектов. Продолжайте оттачивать Ваши навыки. А когда поймете, что легко справляетесь с такими простыми программами, начните писать полноценные приложения  используя редактор  VisualStudio Code и др. Основами Вы уже владеете, поэтому для Вас теперь открыт целый мир полезной информации, которую Вы способны понимать и применять.\r\n“А какие именно полноценные приложения?” Спросите Вы, и будете абсолютно правы. Позвольте привести Вам некоторые примеры приложений, которые Вы можете создать с помощью Python:\r\n\r\nНастольные приложения с графическим интерфейсом:\r\n\r\nБиблиотеки Python, такие как Tkinter, PyQt или Kivy, можно использовать для создания настольных приложений с удобным графическим интерфейсом.\r\n\r\nPygame – популярный выбор для разработки игр на Python. Он не так мощен, как Unity или Unreal Engine, но подходит для более простых 2D игр.\r\n\r\nФреймворки Python, такие как Django, Flask, Pyramid и др., можно использовать для создания мощных, функционально насыщенных веб-приложений.\r\n\r\nВы можете разрабатывать интерактивные чат-боты с использованием таких библиотек Python, как ChatterBot.\r\n\r\nС помощью инструментов, таких как Scapy, nmap-python и др., можно разрабатывать приложения, связанные с безопасностью, на Python.\r\n\r\nБиблиотеки Python для обработки данных, такие как pandas, и библиотеки для визуализации, такие как Matplotlib и Seaborn, можно использовать для разработки приложений, которые обрабатывают, анализируют и визуализируют данные.\r\n\r\nБиблиотеки, такие как TensorFlow, PyTorch, scikit-learn и др., позволяют разработчикам создавать приложения AI и машинного обучения с помощью Python.\r\n\r\nPython широко используется в научных вычислениях с помощью таких библиотек, как SciPy, NumPy и др.\r\n\r\nБиблиотеки, такие как BeautifulSoup и Scrapy, можно использовать для разработки приложений, которые извлекают данные из веб-сайтов.\r\n\r\nПростота Python делает его отличным языком для написания скриптов автоматизации. Например, вы можете автоматизировать повторяющиеся задачи, такие как перемещение файлов, анализ логов и др.\r\n\r\nБиблиотеки, такие как OpenCV и Pillow, можно использовать для создания приложений, которые работают с обработкой изображений.\r\n\r\nВ Python есть встроенные библиотеки, такие как asyncio, которые вы можете использовать для написания серверных, и других сетевых приложений.\r\n\r\nДумаю этого достаточно для того, чтобы Вы поняли – насколько мощным языком программирования Вы теперь владеете. Выбирайте понравившееся Вам направление и начинайте практиковаться.', 'photos/2026/$m/09/8.jpg', '2026-07-09 19:36:40.721974', '2026-07-11 11:16:24.566853', 1, 3);

